//! User-facing agent configuration.
//!
//! Loaded from `canon-agent-prompts/agent_config.toml`.
//! `agents.cards[0].agent_url` is required. Missing or malformed config aborts startup.

use serde::Deserialize;
use std::path::Path;

#[derive(Debug, Deserialize)]
pub struct AgentConfig {
    /// ChatGPT tab URL opened for every LLM call. Required.
    pub chatgpt_url: String,

    /// Override max ticks (0 = run forever).
    pub max_ticks: Option<u64>,

    /// Meta-tick interval.
    pub meta_tick_interval: Option<u64>,

    /// Policy update interval.
    pub policy_update_interval: Option<u64>,
}

impl AgentConfig {
    /// Load from `<workspace>/canon-agent-prompts/agent_config.toml`. Errors if missing or malformed.
    pub fn load(workspace: &Path) -> Result<Self, String> {
        let primary = workspace.join("canon-agent-prompts").join("agent_config.toml");
        let fallback = workspace.join("..").join("canon-agent-prompts").join("agent_config.toml");
        let (path, raw) = match std::fs::read_to_string(&primary) {
            Ok(raw) => (primary, raw),
            Err(_) => {
                let raw = std::fs::read_to_string(&fallback).map_err(|e| format!("failed to read {}: {e}", fallback.display()))?;
                (fallback, raw)
            }
        };
        let cfg: RawAgentConfig = toml::from_str(&raw).map_err(|e| format!("failed to parse {}: {e}", path.display()))?;
        let chatgpt_url = cfg.agents.cards.first().map(|c| c.agent_url.clone()).ok_or_else(|| format!("agent_config.toml missing agents.cards[0].agent_url"))?;
        Ok(AgentConfig {
            chatgpt_url,
            max_ticks: cfg.runner.as_ref().and_then(|r| r.max_ticks),
            meta_tick_interval: cfg.runner.as_ref().and_then(|r| r.meta_tick_interval),
            policy_update_interval: cfg.runner.as_ref().and_then(|r| r.policy_update_interval),
        })
    }
}

#[derive(Debug, Deserialize)]
struct RawAgentConfig {
    #[serde(default)]
    pub runner: Option<RawRunner>,
    pub agents: RawAgents,
}

#[derive(Debug, Deserialize)]
struct RawRunner {
    pub max_ticks: Option<u64>,
    pub meta_tick_interval: Option<u64>,
    pub policy_update_interval: Option<u64>,
}

#[derive(Debug, Deserialize)]
struct RawAgents {
    pub cards: Vec<RawAgentCard>,
}

#[derive(Debug, Deserialize)]
struct RawAgentCard {
    pub agent_url: String,
}

//! Bootstrap helpers — build the standard 5-node capability graph and
//! a seed RefactorProposal so the runner loop has something to dispatch.
//!
//! Standard graph topology:
//!
//!   Observer(Observe) → Reasoner(Learn) → Prover(Decide) → Judge(Plan) → Mutator(Act)
//!
//! Each node is assigned the minimum IrField reads required for its role.
//! Edges carry proof_confidence = 0.7 (unverified but trusted by default).
//!
//! No LLM calls. No unsafe. Pure construction.
use super::capability::{AgentGraph, AgentNode, CapabilityEdge, CapabilityKind, IrField};
use super::pipelines::refactor::{RefactorKind, RefactorProposal, RefactorTarget};
use crate::ir::PipelineStage;
/// Default proof_confidence on all bootstrapped edges.
/// Must satisfy c^(chain_length-1) >= base_trust_threshold.
/// For a 5-node linear chain with threshold 0.5: c >= 0.5^(1/4) ≈ 0.841.
const DEFAULT_EDGE_CONFIDENCE: f64 = 0.85;
/// Build the standard 5-node Observer→Reasoner→Prover→Judge→Mutator graph.
///
/// This is the minimum viable graph for one full pipeline run.
/// All edges carry DEFAULT_EDGE_CONFIDENCE.
pub fn seed_capability_graph() -> AgentGraph {
    let mut g = AgentGraph::new();
    g.add_node(AgentNode {
        id: "observer".to_string(),
        kind: CapabilityKind::Observer,
        label: "IR Observer".to_string(),
        reads: vec![IrField::Modules, IrField::ModuleEdges, IrField::Functions, IrField::CallEdges, IrField::Structs, IrField::Traits, IrField::Deltas, IrField::Errors],
        writes: vec![],
        stage: PipelineStage::Observe,
    });
    g.add_node(AgentNode {
        id: "reasoner".to_string(),
        kind: CapabilityKind::Reasoner,
        label: "Refactor Reasoner".to_string(),
        reads: vec![IrField::Modules, IrField::Functions, IrField::Proposals, IrField::Judgments, IrField::RewardDeltas, IrField::PolicyParameters, IrField::Learning],
        writes: vec![IrField::Proposals],
        stage: PipelineStage::Learn,
    });
    g.add_node(AgentNode {
        id: "prover".to_string(),
        kind: CapabilityKind::Prover,
        label: "SMT Prover".to_string(),
        reads: vec![IrField::Proofs, IrField::Deltas, IrField::Functions, IrField::Proposals],
        writes: vec![IrField::Proofs],
        stage: PipelineStage::Decide,
    });
    g.add_node(AgentNode {
        id: "judge".to_string(),
        kind: CapabilityKind::Judge,
        label: "Proposal Judge".to_string(),
        reads: vec![IrField::Judgments, IrField::JudgmentPredicates, IrField::Admissions, IrField::Proposals, IrField::Proofs],
        writes: vec![IrField::Judgments, IrField::Admissions],
        stage: PipelineStage::Plan,
    });
    g.add_node(AgentNode {
        id: "mutator".to_string(),
        kind: CapabilityKind::Mutator,
        label: "Delta Mutator".to_string(),
        reads: vec![IrField::Admissions, IrField::AppliedDeltas, IrField::Deltas, IrField::Modules, IrField::Functions],
        writes: vec![IrField::AppliedDeltas],
        stage: PipelineStage::Act,
    });
    g.add_edge(CapabilityEdge { from: "observer".to_string(), to: "reasoner".to_string(), proof_confidence: DEFAULT_EDGE_CONFIDENCE });
    g.add_edge(CapabilityEdge { from: "reasoner".to_string(), to: "prover".to_string(), proof_confidence: DEFAULT_EDGE_CONFIDENCE });
    g.add_edge(CapabilityEdge { from: "prover".to_string(), to: "judge".to_string(), proof_confidence: DEFAULT_EDGE_CONFIDENCE });
    g.add_edge(CapabilityEdge { from: "judge".to_string(), to: "mutator".to_string(), proof_confidence: DEFAULT_EDGE_CONFIDENCE });
    g
}
/// Build a seed RefactorProposal for the first pipeline run.
///
/// Targets the first module in the IR by convention.
/// The runner increments the id each tick so proposals stay unique.
pub fn seed_refactor_proposal(target_module_id: &str) -> RefactorProposal {
    RefactorProposal::new(
        "seed",
        RefactorKind::SplitModule,
        RefactorTarget { artifact_id: target_module_id.to_string(), artifact_kind: "module".to_string() },
        "Bootstrap proposal — Observer will refine this rationale on first run.",
        PipelineStage::Observe,
    )
}

use serde::{Deserialize, Serialize};

use crate::ir::PipelineStage;

/// Unique identifier for a single agent call invocation.
pub type AgentCallId = String;

/// The input payload handed to one stateless LLM call.
/// Contains only the IR slice the node is permitted to read.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AgentCallInput {
    pub call_id: AgentCallId,
    pub node_id: String,
    /// Serialised IR slice (only the fields declared in CapabilityNode::reads).
    pub ir_slice: serde_json::Value,
    /// Any outputs from predecessor nodes in this tick's call chain.
    pub predecessor_outputs: Vec<AgentCallOutput>,
    pub stage: PipelineStage,
}

/// The output produced by one stateless LLM call.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AgentCallOutput {
    pub call_id: AgentCallId,
    pub node_id: String,
    /// Structured result payload — interpretation depends on CapabilityKind.
    pub payload: serde_json::Value,
    /// Proof id generated during this call, if any.
    pub proof_id: Option<String>,
    /// Delta ids emitted during this call, if any.
    pub emitted_delta_ids: Vec<String>,
    pub stage: PipelineStage,
}

/// Result of dispatching a single agent call.
#[derive(Debug, Clone)]
pub enum AgentCallResult {
    Ok(AgentCallOutput),
    Err(AgentCallError),
}

/// Errors that can occur when dispatching an agent call.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum AgentCallError {
    /// The node id referenced does not exist in the capability graph.
    UnknownNode(String),
    /// The IR slice could not be constructed (field access violation).
    SliceError(String),
    /// The LLM call returned a payload that failed schema validation.
    InvalidPayload(String),
    /// A predecessor node's output was missing when required.
    MissingPredecessorOutput(String),
    /// Proof confidence on an incoming edge was below the required threshold.
    InsufficientTrust { node_id: String, score: f64, required: f64 },
}

impl std::fmt::Display for AgentCallError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            AgentCallError::UnknownNode(id) => write!(f, "unknown capability node: {id}"),
            AgentCallError::SliceError(msg) => write!(f, "IR slice error: {msg}"),
            AgentCallError::InvalidPayload(msg) => write!(f, "invalid payload: {msg}"),
            AgentCallError::MissingPredecessorOutput(id) => {
                write!(f, "missing predecessor output from node: {id}")
            }
            AgentCallError::InsufficientTrust { node_id, score, required } => {
                write!(f, "insufficient trust on node {node_id}: score={score:.3} required={required:.3}")
            }
        }
    }
}

impl std::error::Error for AgentCallError {}

use serde::{Deserialize, Serialize};
use std::collections::HashMap;
/// Which top-level fields of CanonicalIr this node is allowed to read.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq, Hash)]
#[serde(rename_all = "snake_case")]
pub enum IrField {
    Modules,
    ModuleEdges,
    Structs,
    Enums,
    Traits,
    ImplBlocks,
    Functions,
    CallEdges,
    TickGraphs,
    SystemGraphs,
    LoopPolicies,
    Ticks,
    TickEpochs,
    PolicyParameters,
    Plans,
    Executions,
    Admissions,
    AppliedDeltas,
    GpuFunctions,
    Proposals,
    Judgments,
    JudgmentPredicates,
    Deltas,
    Proofs,
    Learning,
    Errors,
    Dependencies,
    FileHashes,
    RewardDeltas,
    WorldModel,
    GoalMutations,
}
/// The role a capability node plays in the L3 graph.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum CapabilityKind {
    /// Reads IR, emits observation deltas.
    Observer,
    /// Proposes structural or behavioural refactors.
    Reasoner,
    /// Generates or checks SMT proofs.
    Prover,
    /// Accepts or rejects proposals via judgment.
    Judge,
    /// Applies admitted deltas to produce new IR.
    Mutator,
    /// Computes reward signal from execution records.
    Evaluator,
    /// Rewrites graph topology (L7 only).
    MetaAgent,
}
/// A single node in the L3 capability graph.
/// Each node corresponds to one stateless LLM call invocation.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AgentNode {
    pub id: String,
    pub kind: CapabilityKind,
    /// Human-readable label for this node.
    pub label: String,
    /// Exact IR fields this node may read. Enforced at call-slice time.
    pub reads: Vec<IrField>,
    /// Exact IR fields this node may write (via emitted deltas only).
    pub writes: Vec<IrField>,
    /// Which pipeline stage this node belongs to.
    pub stage: crate::ir::PipelineStage,
}
/// A directed edge in the capability graph.
/// Data flows from `from` to `to` — the output of one call feeds the next.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CapabilityEdge {
    pub from: String,
    pub to: String,
    /// Proof confidence on this edge: 0.0 = unverified, 1.0 = fully proven.
    pub proof_confidence: f64,
}
/// The L3 capability graph.
/// Lives beside CanonicalIr and LayoutGraph — not inside either.
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct AgentGraph {
    pub nodes: Vec<AgentNode>,
    pub edges: Vec<CapabilityEdge>,
}
impl AgentGraph {
    pub fn new() -> Self {
        Self::default()
    }
    pub fn add_node(&mut self, node: AgentNode) {
        self.nodes.push(node);
    }
    pub fn add_edge(&mut self, edge: CapabilityEdge) {
        self.edges.push(edge);
    }
    pub fn node(&self, id: &str) -> Option<&AgentNode> {
        self.nodes.iter().find(|n| n.id == id)
    }
    /// Returns all nodes that feed into `id` (predecessors).
    pub fn predecessors(&self, id: &str) -> Vec<&AgentNode> {
        self.edges.iter().filter(|e| e.to == id).filter_map(|e| self.node(&e.from)).collect()
    }
    /// Returns all nodes that `id` feeds into (successors).
    pub fn successors(&self, id: &str) -> Vec<&AgentNode> {
        self.edges.iter().filter(|e| e.from == id).filter_map(|e| self.node(&e.to)).collect()
    }
    /// Validates that every edge references existing node ids.
    pub fn validate_edges(&self) -> Vec<String> {
        let ids: std::collections::HashSet<&str> = self.nodes.iter().map(|n| n.id.as_str()).collect();
        let mut violations = Vec::new();
        for edge in &self.edges {
            if !ids.contains(edge.from.as_str()) {
                violations.push(format!("edge from unknown node: {}", edge.from));
            }
            if !ids.contains(edge.to.as_str()) {
                violations.push(format!("edge to unknown node: {}", edge.to));
            }
        }
        violations
    }
    /// Computes graph entropy H(G) = -Σ π(v,u) log π(v,u)
    /// where π is uniform over outgoing edges per node.
    pub fn entropy(&self) -> f64 {
        let mut h = 0.0_f64;
        for node in &self.nodes {
            let out_edges: Vec<&CapabilityEdge> = self.edges.iter().filter(|e| e.from == node.id).collect();
            let n = out_edges.len() as f64;
            if n > 1.0 {
                let p = 1.0 / n;
                h += -n * p * p.ln();
            }
        }
        h
    }
    /// Returns node trust scores τ(v) propagated from proof_confidence on edges.
    /// Nodes with no predecessors get trust = 1.0 (root axiom).
    pub fn trust_scores(&self) -> HashMap<String, f64> {
        let mut scores: HashMap<String, f64> = self.nodes.iter().map(|n| (n.id.clone(), 1.0_f64)).collect();
        for _ in 0..self.nodes.len() {
            for node in &self.nodes {
                let preds: Vec<&CapabilityEdge> = self.edges.iter().filter(|e| e.to == node.id).collect();
                if preds.is_empty() {
                    continue;
                }
                let sum: f64 = preds.iter().map(|e| e.proof_confidence * scores.get(e.from.as_str()).copied().unwrap_or(1.0)).sum();
                scores.insert(node.id.clone(), sum / preds.len() as f64);
            }
        }
        scores
    }
}

//! AgentCallDispatcher — builds AgentCallInput from graph + IR.
//!
//! Does not make LLM calls. Produces a fully-formed AgentCallInput
//! ready to hand to any LLM provider. Trust threshold enforced here.
use super::call::{AgentCallError, AgentCallInput, AgentCallOutput};
use super::capability::AgentGraph;
use super::slice::slice_ir_fields;
use crate::ir::SystemState;
use std::collections::HashMap;
/// Minimum proof_confidence required on all incoming edges before
/// a node is permitted to receive a call. Nodes with no predecessors
/// are exempt (root axiom trust = 1.0).
pub const DEFAULT_TRUST_THRESHOLD: f64 = 0.5;
pub struct AgentScheduler<'a> {
    graph: &'a AgentGraph,
    ir: &'a SystemState,
    /// Completed outputs from earlier calls in this tick, keyed by node_id.
    completed: HashMap<String, AgentCallOutput>,
    trust_threshold: f64,
}
impl<'a> AgentScheduler<'a> {
    pub fn new(graph: &'a AgentGraph, ir: &'a SystemState) -> Self {
        Self { graph, ir, completed: HashMap::new(), trust_threshold: DEFAULT_TRUST_THRESHOLD }
    }
    pub fn with_trust_threshold(mut self, threshold: f64) -> Self {
        self.trust_threshold = threshold;
        self
    }
    /// Record a completed call output so successors can access it.
    pub fn record_output(&mut self, output: AgentCallOutput) {
        self.completed.insert(output.node_id.clone(), output);
    }
    /// Build a fully-formed AgentCallInput for `node_id`.
    /// Returns Err if the node is unknown, trust is insufficient,
    /// or a required predecessor output is missing.
    pub fn dispatch(&self, node_id: &str) -> Result<AgentCallInput, AgentCallError> {
        let node = self.graph.node(node_id).ok_or_else(|| AgentCallError::UnknownNode(node_id.to_string()))?;
        let trust_scores = self.graph.trust_scores();
        let score = trust_scores.get(node_id).copied().unwrap_or(1.0);
        let preds = self.graph.predecessors(node_id);
        if !preds.is_empty() && score < self.trust_threshold {
            return Err(AgentCallError::InsufficientTrust { node_id: node_id.to_string(), score, required: self.trust_threshold });
        }
        let ir_slice = slice_ir_fields(self.ir, &node.reads);
        let mut predecessor_outputs = Vec::new();
        for pred in &preds {
            let output = self.completed.get(pred.id.as_str()).ok_or_else(|| AgentCallError::MissingPredecessorOutput(pred.id.clone()))?;
            predecessor_outputs.push(output.clone());
        }
        let call_id = format!("{}#{}", node_id, self.completed.len());
        Ok(AgentCallInput { call_id, node_id: node_id.to_string(), ir_slice, predecessor_outputs, stage: node.stage })
    }
    /// Returns node ids in topological dispatch order (predecessors first).
    /// Errors if the graph contains a cycle.
    pub fn topological_call_order(&self) -> Result<Vec<String>, AgentCallError> {
        let mut visited: std::collections::HashSet<String> = Default::default();
        let mut in_progress: std::collections::HashSet<String> = Default::default();
        let mut order: Vec<String> = Vec::new();
        for node in &self.graph.nodes {
            if !visited.contains(&node.id) {
                self.visit(&node.id, &mut visited, &mut in_progress, &mut order)?;
            }
        }
        Ok(order)
    }
    fn visit(&self, node_id: &str, visited: &mut std::collections::HashSet<String>, in_progress: &mut std::collections::HashSet<String>, order: &mut Vec<String>) -> Result<(), AgentCallError> {
        if in_progress.contains(node_id) {
            return Err(AgentCallError::SliceError(format!("cycle detected at node: {node_id}")));
        }
        if visited.contains(node_id) {
            return Ok(());
        }
        in_progress.insert(node_id.to_string());
        for pred in self.graph.predecessors(node_id) {
            self.visit(&pred.id.clone(), visited, in_progress, order)?;
        }
        in_progress.remove(node_id);
        visited.insert(node_id.to_string());
        order.push(node_id.to_string());
        Ok(())
    }
}

use super::capability::AgentGraph;
use std::fs;
use std::path::Path;
/// Loads a CapabilityGraph from disk. Returns a default empty graph if the
/// file does not exist (first run).
pub fn load_capability_graph(path: &Path) -> Result<AgentGraph, Box<dyn std::error::Error>> {
    if !path.exists() {
        return Ok(AgentGraph::default());
    }
    let data = fs::read(path)?;
    Ok(serde_json::from_slice(&data)?)
}
/// Saves a CapabilityGraph to disk as pretty-printed JSON.
pub fn save_capability_graph(graph: &AgentGraph, path: &Path) -> Result<(), Box<dyn std::error::Error>> {
    let json = serde_json::to_string_pretty(graph)?;
    fs::write(path, json)?;
    Ok(())
}

