//! LLM Provider Adapter
//!
//! Responsibility:
//!   Transform AgentCallInput → LLM turn → structured AgentCallOutput.
//!
//! Contract:
//!   - Stateless
//!   - No disk I/O
//!   - No polling
//!   - JSON-only response contract
//!   - WebSocket transport abstracted via WsBridge
//!
//! Pipeline:
//!   Input → PromptBuilder → WsBridge → JsonExtractor → OutputAssembler

use serde_json::Value;

use super::call::{AgentCallInput, AgentCallOutput};
use super::ws_server::{WsBridge, WsBridgeError};

/// ------------------------------------------------------------------------
/// Error Domain
/// ------------------------------------------------------------------------

#[derive(Debug)]
pub enum LlmProviderError {
    Transport(WsBridgeError),
    MissingJsonFence,
    JsonDecodeFailure(String),
}

impl std::fmt::Display for LlmProviderError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Transport(e) => write!(f, "transport error: {e}"),
            Self::MissingJsonFence => write!(f, "no fenced json block found"),
            Self::JsonDecodeFailure(e) => write!(f, "invalid json payload: {e}"),
        }
    }
}

impl std::error::Error for LlmProviderError {}

impl From<WsBridgeError> for LlmProviderError {
    fn from(e: WsBridgeError) -> Self {
        Self::Transport(e)
    }
}

/// Send a fully-formed prompt string to the LLM and return the extracted
/// JSON payload. Bypasses PromptBuilder — caller owns the full prompt.
pub async fn call_llm_raw(bridge: &WsBridge, prompt: String, url: &str) -> Result<Value, LlmProviderError> {
    bridge.wait_for_connection().await;
    let tab_id = bridge.open_fresh_tab_with_url(url.to_string()).await.map_err(LlmProviderError::Transport)?;
    let raw = bridge.send_turn(tab_id, prompt).await.map_err(LlmProviderError::Transport)?;
    JsonExtractor::extract(&raw)
}

/// ------------------------------------------------------------------------
/// Public Entry Point
/// ------------------------------------------------------------------------

pub async fn call_llm(bridge: &WsBridge, input: &AgentCallInput, url: &str) -> Result<AgentCallOutput, LlmProviderError> {
    let prompt = PromptBuilder::new(input).build();

    bridge.wait_for_connection().await;

    // clean mode: suppress call_llm url log
    let tab_id = bridge.open_fresh_tab_with_url(url.to_string()).await.map_err(LlmProviderError::Transport)?;

    // clean mode: suppress TURN routing log

    let raw_response = bridge.send_turn(tab_id, prompt).await.map_err(LlmProviderError::Transport)?;

    let payload = JsonExtractor::extract(&raw_response)?;

    Ok(OutputAssembler::assemble(input, payload))
}

/// ------------------------------------------------------------------------
/// Prompt Builder
/// ------------------------------------------------------------------------

struct PromptBuilder<'a> {
    input: &'a AgentCallInput,
}

impl<'a> PromptBuilder<'a> {
    fn new(input: &'a AgentCallInput) -> Self {
        Self { input }
    }

    fn build(&self) -> String {
        let stage = format!("{:?}", self.input.stage);
        let ir = self.serialize_ir();
        let predecessors = self.serialize_predecessors();
        let required = required_fields_for_stage(&stage);

        format!(
            "Capability Node Execution\n\
             ------------------------\n\
             Stage: {stage}\n\
             Node: {node}\n\
             Call: {call}\n\
             \n\
             IR Slice:\n\
             ```json\n{ir}\n```\n\
             \n\
             Predecessor Outputs:\n\
             {predecessors}\n\
             \n\
             Required Output:\n\
             Respond with ONE fenced ```json block only.\n\
             Must include fields:\n\
             {required}",
            stage = stage,
            node = self.input.node_id,
            call = self.input.call_id,
            ir = ir,
            predecessors = predecessors,
            required = required,
        )
    }

    fn serialize_ir(&self) -> String {
        serde_json::to_string_pretty(&self.input.ir_slice).unwrap_or_else(|_| "{}".into())
    }

    fn serialize_predecessors(&self) -> String {
        if self.input.predecessor_outputs.is_empty() {
            return "none".into();
        }

        self.input
            .predecessor_outputs
            .iter()
            .map(|p| format!("node={} stage={:?} payload={}", p.node_id, p.stage, serde_json::to_string(&p.payload).unwrap_or_default()))
            .collect::<Vec<_>>()
            .join("\n")
    }
}

/// ------------------------------------------------------------------------
/// JSON Extraction
/// ------------------------------------------------------------------------

pub struct JsonExtractor;

impl JsonExtractor {
    pub fn extract(text: &str) -> Result<Value, LlmProviderError> {
        let start = Self::find_open(text)?;
        let content = &text[start..];
        let json_str = Self::slice_json(content)?;
        serde_json::from_str(json_str).map_err(|e| LlmProviderError::JsonDecodeFailure(e.to_string()))
    }

    fn find_open(text: &str) -> Result<usize, LlmProviderError> {
        text.find("```json").or_else(|| text.find("```JSON")).map(|i| i + 7).ok_or(LlmProviderError::MissingJsonFence)
    }

    fn slice_json(text: &str) -> Result<&str, LlmProviderError> {
        let end = text.rfind("```").ok_or(LlmProviderError::MissingJsonFence)?;
        Ok(text[..end].trim())
    }
}

/// ------------------------------------------------------------------------
/// Output Assembly
/// ------------------------------------------------------------------------

struct OutputAssembler;

impl OutputAssembler {
    fn assemble(input: &AgentCallInput, payload: Value) -> AgentCallOutput {
        let proof_id = payload.get("proof_id").and_then(|v| v.as_str()).map(str::to_owned);

        let emitted_delta_ids = payload.get("emitted_delta_ids").and_then(|v| v.as_array()).map(|arr| arr.iter().filter_map(|v| v.as_str().map(str::to_owned)).collect()).unwrap_or_default();

        AgentCallOutput { call_id: input.call_id.clone(), node_id: input.node_id.clone(), payload, proof_id, emitted_delta_ids, stage: input.stage.clone() }
    }
}

/// ------------------------------------------------------------------------
/// Stage Schema
/// ------------------------------------------------------------------------

fn required_fields_for_stage(stage: &str) -> &'static str {
    match stage {
        "Observe" => {
            r#"{
  "observation": "<string>",
  "hottest_modules": ["<module_id>"],
  "issues_found": ["<string>"]
}"#
        }

        "Learn" => {
            r#"{
  "rationale": "<string>",
  "proposed_kind": "<split_module|merge_modules|move_artifact|rename_artifact|add_edge|remove_edge>",
  "target_artifact_id": "<string>",
  "destination_id": "<string|null>",
  "change_payload": {
    "type": "<add_module|add_struct|add_field|add_trait|add_trait_function|add_impl|add_function|add_enum|add_enum_variant|update_struct_visibility|remove_field|rename_artifact|add_module_edge|add_call_edge|record_reward>",
    "...fields per type — examples below...": null,
    "ADD_MODULE":    { "module_id": "<id>", "name": "<name>", "visibility": "<public|private|pub_crate|pub_super>", "description": "<string>" },
    "ADD_STRUCT":    { "module": "<module_id>", "struct_id": "<id>", "name": "<name>" },
    "ADD_FIELD":     { "struct_id": "<id>", "field": { "name": "<name>", "ty": { "name": "<type>", "kind": "scalar", "params": [], "ref_kind": "none" } } },
    "ADD_TRAIT":     { "module": "<module_id>", "trait_id": "<id>", "name": "<name>" },
    "ADD_FUNCTION":  { "function_id": "<id>", "impl_id": "<id>", "signature": { "name": "<name>", "visibility": "public", "is_async": false, "is_unsafe": false, "inputs": [], "outputs": [], "generics": [], "where_clauses": [], "lifetime_params": [], "trait_function": "<trait_fn_id>", "doc": null } },
    "ADD_MODULE_EDGE": { "from": "<module_id>", "to": "<module_id>", "rationale": "<string>" },
    "RENAME_ARTIFACT": { "kind": "<module|struct|function>", "old_id": "<id>", "new_id": "<id>" }
  }
}"#
        }

        "Decide" => {
            r#"{
  "proof_id": "<string>",
  "verification_notes": "<string>"
}"#
        }

        "Plan" => {
            r#"{
  "decision": "<accept|reject>",
  "admission_id": "<string>",
  "rationale": "<string>"
}"#
        }

        _ => {
            r#"{
  "observation": "<string>",
  "rationale": "<string>"
}"#
        }
    }
}

//! L7 Meta-tick — CapabilityGraph self-rewrite driven by reward signal.
//!
//! The meta-tick fires every N pipeline runs. It reads ranked_nodes()
//! from the RewardLedger, identifies underperforming nodes, and proposes
//! topology mutations to the CapabilityGraph itself.
//!
//! Safety: every proposed graph mutation is checked against:
//!   1. Entropy bound  — H(G') must not deviate from H(G) by more than η
//!   2. Minimum nodes  — graph must retain at least MIN_NODES after mutation
//!   3. Connectivity   — every remaining node must have a path to at least one successor
//!
//! This is the Φ: G → G' operator made concrete.
//! No LLM calls. No unsafe. Pure graph arithmetic.
use super::capability::{AgentGraph, AgentNode, CapabilityEdge, CapabilityKind};
use super::reward::NodeRewardLedger;
use crate::ir::PipelineStage;
/// Minimum number of nodes the capability graph must retain after a meta-tick.
pub const MIN_NODES: usize = 3;
/// Maximum entropy deviation allowed between G and Φ(G).
pub const MAX_ENTROPY_DELTA: f64 = 0.5;
/// EMA reward below this threshold marks a node as underperforming.
pub const UNDERPERFORM_THRESHOLD: f64 = -0.1;
/// A single proposed mutation to the CapabilityGraph topology.
#[derive(Debug, Clone)]
pub enum GraphMutation {
    /// Remove a node and all its edges.
    RemoveNode { node_id: String },
    /// Add a new edge between two existing nodes.
    AddEdge { from: String, to: String, proof_confidence: f64 },
    /// Remove an edge between two nodes.
    RemoveEdge { from: String, to: String },
    /// Promote a node to MetaAgent kind.
    PromoteToMetaAgent { node_id: String },
}
/// Error returned when a meta-tick mutation is rejected.
#[derive(Debug, Clone)]
pub enum GraphEvolutionError {
    /// Graph entropy deviated beyond MAX_ENTROPY_DELTA.
    EntropyBoundExceeded { before: f64, after: f64, delta: f64 },
    /// Mutation would drop graph below MIN_NODES.
    TooFewNodes { remaining: usize },
    /// Target node does not exist.
    UnknownNode(String),
    /// Mutation would disconnect a node entirely.
    DisconnectedNode(String),
    /// No mutations were proposed (graph is already optimal).
    NothingToDo,
}
impl std::fmt::Display for GraphEvolutionError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            GraphEvolutionError::EntropyBoundExceeded { before, after, delta } => {
                write!(
                    f,
                    "entropy deviation {delta:.4} exceeds bound {MAX_ENTROPY_DELTA:.4} \
                 (before={before:.4} after={after:.4})"
                )
            }
            GraphEvolutionError::TooFewNodes { remaining } => {
                write!(f, "mutation would leave only {remaining} nodes (minimum {MIN_NODES})")
            }
            GraphEvolutionError::UnknownNode(id) => write!(f, "unknown node: {id}"),
            GraphEvolutionError::DisconnectedNode(id) => {
                write!(f, "mutation would disconnect node: {id}")
            }
            GraphEvolutionError::NothingToDo => write!(f, "no mutations proposed"),
        }
    }
}
impl std::error::Error for GraphEvolutionError {}
/// Result of a successful meta-tick.
#[derive(Debug)]
pub struct GraphEvolutionResult {
    /// The mutated capability graph.
    pub graph: AgentGraph,
    /// Mutations that were applied.
    pub applied: Vec<GraphMutation>,
    /// Mutations that were rejected by safety checks.
    pub rejected: Vec<(GraphMutation, GraphEvolutionError)>,
    /// Entropy before mutation.
    pub entropy_before: f64,
    /// Entropy after mutation.
    pub entropy_after: f64,
}
/// Drives one meta-tick over the capability graph.
///
/// Reads the reward ledger to identify underperforming nodes,
/// proposes graph mutations, applies each through safety checks,
/// and returns the mutated graph.
///
/// Returns Err(GraphEvolutionError::NothingToDo) if no mutations are warranted.
pub fn evolve_capability_graph(graph: &AgentGraph, ledger: &NodeRewardLedger) -> Result<GraphEvolutionResult, GraphEvolutionError> {
    let mutations = propose_mutations(graph, ledger);
    if mutations.is_empty() {
        return Err(GraphEvolutionError::NothingToDo);
    }
    let entropy_before = graph.entropy();
    let mut current = graph.clone();
    let mut applied = Vec::new();
    let mut rejected = Vec::new();
    for mutation in mutations {
        match apply_mutation(&current, &mutation) {
            Ok(candidate) => {
                let entropy_after = candidate.entropy();
                let delta = (entropy_after - entropy_before).abs();
                if delta > MAX_ENTROPY_DELTA {
                    rejected.push((mutation, GraphEvolutionError::EntropyBoundExceeded { before: entropy_before, after: entropy_after, delta }));
                    continue;
                }
                if candidate.nodes.len() < MIN_NODES {
                    rejected.push((mutation, GraphEvolutionError::TooFewNodes { remaining: candidate.nodes.len() }));
                    continue;
                }
                if let Some(id) = find_disconnected(&candidate) {
                    rejected.push((mutation, GraphEvolutionError::DisconnectedNode(id)));
                    continue;
                }
                applied.push(mutation);
                current = candidate;
            }
            Err(e) => {
                rejected.push((mutation, e));
            }
        }
    }
    let entropy_after = current.entropy();
    Ok(GraphEvolutionResult { graph: current, applied, rejected, entropy_before, entropy_after })
}
/// Proposes graph mutations based on reward ledger state.
fn propose_mutations(graph: &AgentGraph, ledger: &NodeRewardLedger) -> Vec<GraphMutation> {
    let mut mutations = Vec::new();
    let ranked = ledger.ranked_nodes();
    for entry in &ranked {
        if entry.ema_reward < UNDERPERFORM_THRESHOLD {
            if let Some(node) = graph.node(&entry.node_id) {
                if node.kind != CapabilityKind::MetaAgent {
                    mutations.push(GraphMutation::RemoveNode { node_id: entry.node_id.clone() });
                }
            }
        }
    }
    let has_meta = graph.nodes.iter().any(|n| n.kind == CapabilityKind::MetaAgent);
    if !has_meta {
        if let Some(top) = ranked.first() {
            if top.ema_reward > 0.0 {
                if let Some(node) = graph.node(&top.node_id) {
                    if node.kind != CapabilityKind::MetaAgent {
                        mutations.push(GraphMutation::PromoteToMetaAgent { node_id: top.node_id.clone() });
                    }
                }
            }
        }
    }
    mutations
}
/// Applies a single GraphMutation to a cloned graph, returning the candidate.
fn apply_mutation(graph: &AgentGraph, mutation: &GraphMutation) -> Result<AgentGraph, GraphEvolutionError> {
    let mut next = graph.clone();
    match mutation {
        GraphMutation::RemoveNode { node_id } => {
            if !next.nodes.iter().any(|n| n.id == *node_id) {
                return Err(GraphEvolutionError::UnknownNode(node_id.clone()));
            }
            next.nodes.retain(|n| n.id != *node_id);
            next.edges.retain(|e| e.from != *node_id && e.to != *node_id);
        }
        GraphMutation::AddEdge { from, to, proof_confidence } => {
            if !next.nodes.iter().any(|n| &n.id == from) {
                return Err(GraphEvolutionError::UnknownNode(from.clone()));
            }
            if !next.nodes.iter().any(|n| &n.id == to) {
                return Err(GraphEvolutionError::UnknownNode(to.clone()));
            }
            next.edges.push(CapabilityEdge { from: from.clone(), to: to.clone(), proof_confidence: *proof_confidence });
        }
        GraphMutation::RemoveEdge { from, to } => {
            next.edges.retain(|e| !(e.from == *from && e.to == *to));
        }
        GraphMutation::PromoteToMetaAgent { node_id } => {
            let node = next.nodes.iter_mut().find(|n| n.id == *node_id).ok_or_else(|| GraphEvolutionError::UnknownNode(node_id.clone()))?;
            node.kind = CapabilityKind::MetaAgent;
            node.stage = PipelineStage::Act;
        }
    }
    Ok(next)
}
/// Returns the id of the first node that has no edges at all, or None.
fn find_disconnected(graph: &AgentGraph) -> Option<String> {
    if graph.nodes.len() <= 1 {
        return None;
    }
    for node in &graph.nodes {
        let has_edge = graph.edges.iter().any(|e| e.from == node.id || e.to == node.id);
        if !has_edge {
            return Some(node.id.clone());
        }
    }
    None
}

//! Observer capability node — concrete IR analysis logic.
//!
//! Reads declared IrFields from a slice, produces a structured observation:
//!   - hottest modules   (most call-edge targets)
//!   - largest structs   (most fields)
//!   - deepest call chains (longest path in call graph from each function)
//!
//! Output is a serde_json::Value suitable for feeding directly to the
//! Reasoner as structured JSON (not free text).
//!
//! No LLM calls. No unsafe. Pure graph analysis.
use crate::ir::SystemState;
use serde_json::{json, Value};
use std::collections::HashMap;
/// Top-N limit for each observation category.
const TOP_N: usize = 5;
/// A fully structured observation produced by the Observer node.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct IrAnalysisReport {
    /// Modules ranked by in-degree in the call graph (most-called first).
    pub hottest_modules: Vec<ModuleHeat>,
    /// Structs ranked by field count (largest first).
    pub largest_structs: Vec<StructSize>,
    /// Functions ranked by longest outgoing call chain depth (deepest first).
    pub deepest_call_chains: Vec<CallChainDepth>,
    /// Total counts snapshot.
    pub totals: IrTotals,
}
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct ModuleHeat {
    pub module_id: String,
    pub module_name: String,
    /// Number of call edges that target functions inside this module.
    pub in_degree: usize,
}
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct StructSize {
    pub struct_id: String,
    pub struct_name: String,
    pub field_count: usize,
    pub module_id: String,
}
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct CallChainDepth {
    pub function_id: String,
    pub function_name: String,
    pub depth: usize,
    pub module_id: String,
}
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct IrTotals {
    pub modules: usize,
    pub functions: usize,
    pub structs: usize,
    pub traits: usize,
    pub call_edges: usize,
    pub deltas: usize,
    pub proofs: usize,
}
/// Produce a structured IrObservation from a CanonicalIr.
///
/// This is the concrete implementation for the Observer CapabilityNode.
/// The result serialises directly to JSON and is placed in AgentCallOutput.payload.
pub fn analyze_ir(ir: &SystemState) -> IrAnalysisReport {
    IrAnalysisReport {
        hottest_modules: hottest_modules(ir),
        largest_structs: largest_structs(ir),
        deepest_call_chains: deepest_call_chains(ir),
        totals: IrTotals {
            modules: ir.modules.len(),
            functions: ir.functions.len(),
            structs: ir.structs.len(),
            traits: ir.traits.len(),
            call_edges: ir.call_edges.len(),
            deltas: ir.deltas.len(),
            proofs: ir.proofs.len(),
        },
    }
}
/// Serialises an IrObservation to a JSON Value for use as AgentCallOutput.payload.
pub fn ir_observation_to_json(obs: &IrAnalysisReport) -> Value {
    serde_json::to_value(obs).unwrap_or_else(|_| json!({ "error" : "serialisation failed" }))
}
fn hottest_modules(ir: &SystemState) -> Vec<ModuleHeat> {
    let fn_to_module: HashMap<&str, &str> = ir.functions.iter().map(|f| (f.id.as_str(), f.module.as_str())).collect();
    let mut in_degree: HashMap<&str, usize> = HashMap::new();
    for edge in &ir.call_edges {
        if let Some(&module_id) = fn_to_module.get(edge.callee.as_str()) {
            *in_degree.entry(module_id).or_insert(0) += 1;
        }
    }
    let module_name: HashMap<&str, &str> = ir.modules.iter().map(|m| (m.id.as_str(), m.name.as_str())).collect();
    let mut ranked: Vec<ModuleHeat> = in_degree
        .into_iter()
        .map(|(module_id, deg)| ModuleHeat { module_id: module_id.to_string(), module_name: module_name.get(module_id).copied().unwrap_or(module_id).to_string(), in_degree: deg })
        .collect();
    ranked.sort_by(|a, b| b.in_degree.cmp(&a.in_degree));
    ranked.truncate(TOP_N);
    ranked
}
fn largest_structs(ir: &SystemState) -> Vec<StructSize> {
    let mut ranked: Vec<StructSize> =
        ir.structs.iter().map(|s| StructSize { struct_id: s.id.clone(), struct_name: s.name.as_str().to_string(), field_count: s.fields.len(), module_id: s.module.clone() }).collect();
    ranked.sort_by(|a, b| b.field_count.cmp(&a.field_count));
    ranked.truncate(TOP_N);
    ranked
}
fn deepest_call_chains(ir: &SystemState) -> Vec<CallChainDepth> {
    let mut adj: HashMap<&str, Vec<&str>> = HashMap::new();
    for edge in &ir.call_edges {
        adj.entry(edge.caller.as_str()).or_default().push(edge.callee.as_str());
    }
    let fn_name: HashMap<&str, &str> = ir.functions.iter().map(|f| (f.id.as_str(), f.name.as_str())).collect();
    let fn_module: HashMap<&str, &str> = ir.functions.iter().map(|f| (f.id.as_str(), f.module.as_str())).collect();
    let mut memo: HashMap<&str, usize> = HashMap::new();
    let mut ranked: Vec<CallChainDepth> = ir
        .functions
        .iter()
        .map(|f| {
            let depth = chain_depth(f.id.as_str(), &adj, &mut memo, &mut vec![]);
            CallChainDepth {
                function_id: f.id.clone(),
                function_name: fn_name.get(f.id.as_str()).copied().unwrap_or(&f.id).to_string(),
                depth,
                module_id: fn_module.get(f.id.as_str()).copied().unwrap_or("").to_string(),
            }
        })
        .collect();
    ranked.sort_by(|a, b| b.depth.cmp(&a.depth));
    ranked.truncate(TOP_N);
    ranked
}
/// Recursive DFS with memoisation for longest chain depth.
/// `path` tracks the current DFS path to detect cycles.
fn chain_depth<'a>(node: &'a str, adj: &HashMap<&'a str, Vec<&'a str>>, memo: &mut HashMap<&'a str, usize>, path: &mut Vec<&'a str>) -> usize {
    if let Some(&cached) = memo.get(node) {
        return cached;
    }
    if path.contains(&node) {
        return 0;
    }
    let callees = match adj.get(node) {
        Some(cs) => cs.clone(),
        None => {
            memo.insert(node, 0);
            return 0;
        }
    };
    path.push(node);
    let max_child = callees.iter().map(|callee| chain_depth(callee, adj, memo, path)).max().unwrap_or(0);
    path.pop();
    let depth = 1 + max_child;
    memo.insert(node, depth);
    depth
}

use crate::llm_domains::{is_chatgpt_gg_url, is_chatgpt_url, is_gemini_url};
use serde_json::Value;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SiteType {
    ChatGptPrivate,
    ChatGptGroup,
    Gemini,
    Unknown,
}

impl SiteType {
    pub fn from_url(url: &str) -> Self {
        if is_chatgpt_gg_url(url) {
            return SiteType::ChatGptGroup;
        }
        if is_chatgpt_url(url) {
            return SiteType::ChatGptPrivate;
        }
        if is_gemini_url(url) {
            return SiteType::Gemini;
        }
        SiteType::Unknown
    }
}

/// The result of parsing one inbound frame.
#[derive(Debug)]
pub enum FrameResult {
    Delta(String),
    Snapshot(String),
    Done,
    Ignore,
}

pub fn classify_frame(site: SiteType, raw: &str) -> FrameResult {
    match site {
        SiteType::ChatGptPrivate => classify_chatgpt_private(raw),
        SiteType::ChatGptGroup => classify_chatgpt_group(raw),
        SiteType::Gemini => classify_gemini(raw),
        SiteType::Unknown => FrameResult::Ignore,
    }
}

pub struct FrameAssembler {
    site: SiteType,
    deltas: Vec<String>,
    raw: String,
}

impl FrameAssembler {
    pub fn new(site: SiteType) -> Self {
        Self { site, deltas: Vec::new(), raw: String::new() }
    }

    pub fn set_site(&mut self, site: SiteType) {
        self.site = site;
    }

    pub fn reset(&mut self) {
        self.deltas.clear();
        self.raw.clear();
    }

    pub fn push(&mut self, payload: &str) -> Option<String> {
        match self.site {
            SiteType::Gemini => {
                match classify_frame(self.site, payload) {
                    FrameResult::Snapshot(text) => {
                        // Gemini frames are typically full snapshots; replace instead of append.
                        self.raw.clear();
                        self.raw.push_str(&text);
                        if let Some(fenced) = try_extract_complete_fenced_json(&self.raw) {
                            self.reset();
                            return Some(fenced);
                        }
                        None
                    }
                    FrameResult::Delta(text) => {
                        self.raw.push_str(&text);
                        if let Some(fenced) = try_extract_complete_fenced_json(&self.raw) {
                            self.reset();
                            return Some(fenced);
                        }
                        None
                    }
                    _ => None,
                }
            }
            _ => match classify_frame(self.site, payload) {
                FrameResult::Delta(text) => {
                    self.deltas.push(text);
                    None
                }
                FrameResult::Snapshot(text) => {
                    self.reset();
                    Some(text)
                }
                FrameResult::Done => {
                    let assembled = self.deltas.join("");
                    self.reset();
                    if assembled.is_empty() {
                        None
                    } else {
                        Some(assembled)
                    }
                }
                FrameResult::Ignore => None,
            },
        }
    }
}

fn classify_chatgpt_private(raw: &str) -> FrameResult {
    let data = raw.strip_prefix("data: ").unwrap_or(raw).trim();
    if data.is_empty() {
        return FrameResult::Ignore;
    }
    if data == "[DONE]" {
        return FrameResult::Done;
    }
    let v: Value = match serde_json::from_str(data) {
        Ok(v) => v,
        Err(_) => {
            if let Some(fenced) = extract_fenced_json(data) {
                return FrameResult::Snapshot(fenced);
            }
            return FrameResult::Ignore;
        }
    };

    if let Some(fenced) = find_fenced_json_in_value(&v) {
        return FrameResult::Snapshot(fenced);
    }

    let obj = match v.as_object() {
        Some(o) => o,
        None => return FrameResult::Ignore,
    };
    if obj.get("type").and_then(|t| t.as_str()) == Some("message_stream_complete") {
        return FrameResult::Done;
    }
    if obj.get("type").and_then(|t| t.as_str()) == Some("message") {
        let text = obj.get("content").and_then(|c| c.get("parts")).and_then(|p| p.as_array()).and_then(|a| a.first()).and_then(|v| v.as_str()).unwrap_or("");
        if !text.is_empty() {
            return FrameResult::Snapshot(text.to_string());
        }
    }
    if obj.get("object").and_then(|v| v.as_str()) == Some("chat.completion.chunk") {
        let content = obj.get("choices").and_then(|c| c.as_array()).and_then(|arr| arr.first()).and_then(|c| c.get("delta")).and_then(|d| d.get("content")).and_then(|v| v.as_str());
        return match content {
            Some(s) if !s.is_empty() => FrameResult::Delta(s.to_string()),
            _ => FrameResult::Ignore,
        };
    }
    if let Some(delta) = obj.get("delta").and_then(|d| d.as_str()) {
        if !delta.is_empty() {
            return FrameResult::Delta(delta.to_string());
        }
    }
    if let Some(op) = obj.get("o").and_then(|o| o.as_str()) {
        match op {
            "append" => {
                let p = obj.get("p").and_then(|p| p.as_str()).unwrap_or("");
                if p.contains("parts") {
                    if let Some(s) = obj.get("v").and_then(|v| v.as_str()) {
                        if !s.is_empty() {
                            return FrameResult::Delta(s.to_string());
                        }
                    }
                }
            }
            "patch" => {
                if let Some(arr) = obj.get("v").and_then(|v| v.as_array()) {
                    let mut out = String::new();
                    for item in arr {
                        if item.get("o").and_then(|o| o.as_str()) != Some("append") {
                            continue;
                        }
                        let p = item.get("p").and_then(|p| p.as_str()).unwrap_or("");
                        if p.contains("parts") {
                            if let Some(s) = item.get("v").and_then(|v| v.as_str()) {
                                out.push_str(s);
                            }
                        }
                    }
                    if !out.is_empty() {
                        return FrameResult::Delta(out);
                    }
                }
            }
            _ => {}
        }
    }
    if let Some(text) = obj.get("v").and_then(|v| v.as_str()) {
        if !text.is_empty() {
            return FrameResult::Delta(text.to_string());
        }
    }
    if let Some(arr) = obj.get("v").and_then(|v| v.as_array()) {
        let mut out = String::new();
        for item in arr {
            if item.get("o").and_then(|o| o.as_str()) != Some("append") {
                continue;
            }
            let p = item.get("p").and_then(|p| p.as_str()).unwrap_or("");
            if p.contains("parts") {
                if let Some(s) = item.get("v").and_then(|v| v.as_str()) {
                    out.push_str(s);
                }
            }
        }
        if !out.is_empty() {
            return FrameResult::Delta(out);
        }
    }
    FrameResult::Ignore
}

fn classify_chatgpt_group(raw: &str) -> FrameResult {
    let data = raw.strip_prefix("data: ").unwrap_or(raw).trim();
    if data.is_empty() {
        return FrameResult::Ignore;
    }
    let v: Value = match serde_json::from_str(data) {
        Ok(v) => v,
        Err(_) => return FrameResult::Ignore,
    };
    if let Some(arr) = v.as_array() {
        return classify_calpico_array(arr);
    }
    FrameResult::Ignore
}

fn classify_gemini(raw: &str) -> FrameResult {
    let data = raw.strip_prefix("data: ").unwrap_or(raw).trim();
    if data.is_empty() {
        return FrameResult::Ignore;
    }
    let data = strip_leading_length_line(data);
    // Gemini often sends JSON arrays (wrb.fr) with embedded JSON strings.
    if let Ok(v) = serde_json::from_str::<Value>(data) {
        let mut out = String::new();
        collect_gemini_fragments(&v, &mut out, 0);
        if !out.is_empty() {
            if out.contains("```json") {
                return FrameResult::Snapshot(out);
            }
            return FrameResult::Delta(out);
        }
    } else if let Some(fenced) = extract_fenced_json(data) {
        return FrameResult::Snapshot(fenced);
    }
    FrameResult::Ignore
}

fn strip_leading_length_line(input: &str) -> &str {
    let mut chars = input.chars();
    let mut idx = 0usize;
    let mut saw_digit = false;
    while let Some(c) = chars.next() {
        if c.is_ascii_digit() {
            saw_digit = true;
            idx += c.len_utf8();
            continue;
        }
        if (c == '\n' || c == '\r') && saw_digit {
            let rest = input[idx..].trim_start_matches(['\r', '\n']);
            return rest;
        }
        break;
    }
    input
}

fn collect_gemini_fragments(v: &Value, out: &mut String, depth: usize) {
    // Gemini's wrb.fr payloads are deeply nested; keep this high enough to reach text nodes.
    if depth > 12 {
        return;
    }
    match v {
        Value::String(s) => {
            if s.starts_with('{') || s.starts_with('[') {
                if let Ok(inner) = serde_json::from_str::<Value>(s) {
                    collect_gemini_fragments(&inner, out, depth + 1);
                    return;
                }
            }
            if s.contains("```json") {
                out.push_str(s);
            }
        }
        Value::Array(arr) => {
            for item in arr {
                collect_gemini_fragments(item, out, depth + 1);
            }
        }
        Value::Object(map) => {
            for val in map.values() {
                collect_gemini_fragments(val, out, depth + 1);
            }
        }
        _ => {}
    }
}

fn classify_calpico_array(arr: &[Value]) -> FrameResult {
    for envelope in arr {
        if envelope.get("type").and_then(|t| t.as_str()) != Some("message") {
            continue;
        }
        let payload = match envelope.get("payload") {
            Some(p) => p,
            None => continue,
        };
        if payload.get("type").and_then(|t| t.as_str()) != Some("calpico-message-add") {
            continue;
        }
        let msg = match payload.get("payload").and_then(|p| p.get("message")) {
            Some(m) => m,
            None => continue,
        };
        if msg.get("role").and_then(|r| r.as_str()) != Some("assistant") {
            continue;
        }
        let raw_messages = match msg.get("raw_messages").and_then(|v| v.as_array()) {
            Some(a) => a,
            None => continue,
        };
        for raw_msg in raw_messages {
            let author_role = raw_msg.get("author").and_then(|a| a.get("role")).and_then(|r| r.as_str()).unwrap_or("");
            if author_role != "assistant" {
                continue;
            }
            let channel = raw_msg.get("channel").and_then(|c| c.as_str()).unwrap_or("");
            if channel != "final" {
                continue;
            }
            let text = raw_msg.get("content").and_then(|c| c.get("parts")).and_then(|p| p.as_array()).and_then(|a| a.first()).and_then(|v| v.as_str()).unwrap_or("");
            if !text.is_empty() {
                return FrameResult::Snapshot(text.to_string());
            }
        }
    }
    FrameResult::Ignore
}

fn find_fenced_json_in_value(v: &Value) -> Option<String> {
    match v {
        Value::String(s) => extract_fenced_json(s),
        Value::Array(arr) => arr.iter().find_map(find_fenced_json_in_value),
        Value::Object(map) => map.values().find_map(find_fenced_json_in_value),
        _ => None,
    }
}

fn extract_fenced_json(text: &str) -> Option<String> {
    let start = text.find("```json")?;
    let rest = &text[start..];
    let end = rest.rfind("```")?;
    if end <= 6 {
        return None;
    }
    Some(rest[..end + 3].to_string())
}

pub fn try_extract_complete_fenced_json(raw: &str) -> Option<String> {
    let start = raw.find("```json")?;
    let after_fence = &raw[start + 7..];
    // Find the closing ``` — must be after at least one character of content.
    let end = after_fence.rfind("```")?;
    if end == 0 {
        return None;
    }
    let inner = after_fence[..end].trim();
    // Validate as-is — do NOT re-escape; the string is already decoded by serde.
    if serde_json::from_str::<serde_json::Value>(inner).is_ok() {
        return Some(format!("```json\n{}\n```", inner));
    }
    None
}

//! Reward ledger — closes the learning loop between pipeline outcomes
//! and AgentCallDispatcher trust thresholds.
//!
//! After every PipelineResult the ledger records the outcome, computes
//! a reward signal, updates PolicyParameters via update_policy(), and
//! derives a per-node trust threshold adjustment for the dispatcher.
//!
//! No LLM calls. No unsafe. Pure arithmetic over existing reward infrastructure.
use crate::ir::PolicyParameters;
use crate::runtime::policy_updater::{update_policy, PolicyUpdateError};
use std::collections::HashMap;
/// Outcome of a single pipeline run for a capability node.
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub enum PipelineNodeOutcome {
    /// Proposal was accepted and mutation applied.
    Accepted { reward: f64 },
    /// Proposal was rejected by the Judge stage.
    Rejected { penalty: f64 },
    /// Pipeline halted before Judge (proof missing, drift exceeded, etc.).
    Halted { penalty: f64 },
}
impl PipelineNodeOutcome {
    pub fn reward_value(&self) -> f64 {
        match self {
            PipelineNodeOutcome::Accepted { reward } => *reward,
            PipelineNodeOutcome::Rejected { penalty } => -*penalty,
            PipelineNodeOutcome::Halted { penalty } => -*penalty,
        }
    }
    pub fn was_accepted(&self) -> bool {
        matches!(self, PipelineNodeOutcome::Accepted { .. })
    }
}
/// Per-node reward history entry.
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub struct NodeRewardEntry {
    pub node_id: String,
    pub outcome: PipelineNodeOutcome,
    /// Cumulative exponential moving average of reward for this node.
    pub ema_reward: f64,
    /// How many pipeline runs this node has participated in.
    pub run_count: u64,
}
/// Accumulates pipeline outcomes and derives dispatcher trust thresholds.
#[derive(Debug, Default, serde::Serialize, serde::Deserialize)]
pub struct NodeRewardLedger {
    /// Per-node reward history, keyed by node_id.
    entries: HashMap<String, NodeRewardEntry>,
    /// EMA decay factor α ∈ (0,1). Higher = faster adaptation.
    alpha: f64,
    /// Base trust threshold before reward adjustment.
    base_threshold: f64,
}
impl NodeRewardLedger {
    pub fn new(alpha: f64, base_threshold: f64) -> Self {
        Self { entries: HashMap::new(), alpha, base_threshold }
    }
    /// Record an outcome for a node and update its EMA reward.
    pub fn record(&mut self, node_id: impl Into<String>, outcome: PipelineNodeOutcome) {
        let node_id = node_id.into();
        let reward = outcome.reward_value();
        let entry = self.entries.entry(node_id.clone()).or_insert(NodeRewardEntry { node_id: node_id.clone(), outcome: outcome.clone(), ema_reward: reward, run_count: 0 });
        entry.ema_reward = self.alpha * reward + (1.0 - self.alpha) * entry.ema_reward;
        entry.run_count += 1;
        entry.outcome = outcome;
    }
    /// Derives a trust threshold for a node based on its EMA reward.
    ///
    /// Nodes with positive EMA get lower thresholds (more permissive dispatch).
    /// Nodes with negative EMA get higher thresholds (more scrutiny).
    ///
    /// threshold = clamp(base - ema_reward * scale, 0.1, 0.95)
    pub fn trust_threshold_for(&self, node_id: &str) -> f64 {
        let ema = self.entries.get(node_id).map(|e| e.ema_reward).unwrap_or(0.0);
        let scale = 0.05_f64;
        let raw = self.base_threshold - ema * scale;
        raw.clamp(0.1, 0.95)
    }
    /// Updates PolicyParameters using the aggregate reward across all nodes.
    /// Returns updated parameters or a PolicyUpdateError.
    pub fn update_policy(&self, current: &PolicyParameters) -> Result<PolicyParameters, PolicyUpdateError> {
        let aggregate_reward = self.aggregate_reward();
        update_policy(current, aggregate_reward)
    }
    /// Mean EMA reward across all nodes that have run at least once.
    pub fn aggregate_reward(&self) -> f64 {
        let active: Vec<f64> = self.entries.values().filter(|e| e.run_count > 0).map(|e| e.ema_reward).collect();
        if active.is_empty() {
            return 0.0;
        }
        active.iter().sum::<f64>() / active.len() as f64
    }
    /// Returns all node entries sorted by EMA reward descending.
    /// Useful for surfacing which nodes are performing best.
    pub fn ranked_nodes(&self) -> Vec<&NodeRewardEntry> {
        let mut entries: Vec<&NodeRewardEntry> = self.entries.values().collect();
        entries.sort_by(|a, b| b.ema_reward.partial_cmp(&a.ema_reward).unwrap_or(std::cmp::Ordering::Equal));
        entries
    }
    /// Returns the entry for a node, if it exists.
    pub fn entry_for(&self, node_id: &str) -> Option<&NodeRewardEntry> {
        self.entries.get(node_id)
    }
}

//! Top-level agent runner — drives the full Tier 7 loop.
//!
//! Loop per tick:
//!   1. CapabilityNodeDispatcher::topological_call_order() → ordered node list
//!   2. For each node: dispatcher.dispatch() → AgentCallInput
//!                     call_llm()             → AgentCallOutput
//!                     dispatcher.record_output()
//!   3. run_refactor_pipeline(ir, layout, proposal, stage_outputs) → RefactorResult
//!   4. record_refactor_reward(ledger, node_id, result)
//!   5. Every meta_tick_interval ticks: evolve_capability_graph(graph, ledger) → Φ(G)
//!   6. Every policy_update_interval ticks: ledger.update_policy()
//!
//! No LLM calls inside this file — delegated entirely to llm_provider::call_llm().
//! Async — requires a tokio runtime. WsBridge is passed in from main.
use super::call::AgentCallOutput;
use super::capability::AgentGraph;
use super::dispatcher::AgentScheduler;
use super::llm_provider::{call_llm, LlmProviderError};
use super::meta::evolve_capability_graph;
use super::pipelines::refactor::{record_refactor_reward, run_refactor_pipeline, RefactorError, RefactorKind, RefactorProposal, RefactorTarget};
use super::reward::NodeRewardLedger;
use super::ws_server::WsBridge;
use crate::executor::{execute_deltas, ExecutorError};
use crate::io::{load_capability_graph, save_capability_graph};
use crate::ir::SystemState;
use crate::layout::FileTopology;
use std::fs;
use std::path::{Path, PathBuf};
/// Configuration for one agent run session.
#[derive(Debug, Clone)]
pub struct RunnerConfig {
    /// How many pipeline ticks to run before stopping (0 = run forever).
    pub max_ticks: u64,
    /// ChatGPT tab URL to open for each LLM call.
    pub chatgpt_url: String,
    /// Fire meta-tick every N ticks (0 = never).
    pub meta_tick_interval: u64,
    /// Update policy every N ticks (0 = never).
    pub policy_update_interval: u64,
    /// EMA alpha for reward ledger.
    pub ledger_alpha: f64,
    /// Base trust threshold for dispatcher.
    pub base_trust_threshold: f64,
    /// Path to save the capability graph after each meta-tick.
    pub graph_out: PathBuf,
    /// Path to save the ledger after each tick.
    pub ledger_out: PathBuf,
    /// Path to save the mutated IR after each successful pipeline run.
    pub ir_out: PathBuf,
    /// Workspace root — deltas are applied here and cargo check is run here.
    pub workspace: PathBuf,
}
impl RunnerConfig {
    pub fn new(graph_out: PathBuf, ledger_out: PathBuf, ir_out: PathBuf) -> Self {
        Self {
            max_ticks: 0,
            chatgpt_url: String::new(),
            meta_tick_interval: 10,
            policy_update_interval: 5,
            ledger_alpha: 0.1,
            base_trust_threshold: 0.5,
            graph_out,
            ledger_out,
            ir_out,
            workspace: PathBuf::from("."),
        }
    }
}
/// Errors from the agent runner.
#[derive(Debug)]
pub enum RunnerError {
    /// Dispatcher could not produce a call order.
    Dispatch(crate::call::AgentCallError),
    /// LLM provider failed for a node.
    Llm { node_id: String, error: LlmProviderError },
    /// No stage outputs were collected (empty graph).
    NoOutputs,
    /// I/O error persisting graph or ledger.
    Io(String),
}
impl std::fmt::Display for RunnerError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            RunnerError::Dispatch(e) => write!(f, "dispatch error: {e}"),
            RunnerError::Llm { node_id, error } => {
                write!(f, "llm error on node {node_id}: {error}")
            }
            RunnerError::NoOutputs => {
                write!(f, "no stage outputs collected — graph may be empty")
            }
            RunnerError::Io(e) => write!(f, "i/o error: {e}"),
        }
    }
}
impl std::error::Error for RunnerError {}
/// Statistics for one completed tick.
#[derive(Debug)]
pub struct TickStats {
    pub tick_number: u64,
    pub nodes_called: usize,
    pub llm_errors: usize,
    pub pipeline_reward: Option<f64>,
    pub pipeline_error: Option<String>,
    pub meta_tick_fired: bool,
    pub policy_updated: bool,
}
/// Runs the Tier 7 agent loop.
///
/// `ir` and `layout` are the starting state — they are updated in-place
/// after each successful pipeline run.
/// `graph` is the CapabilityGraph — mutated by meta-ticks.
/// `proposal_seed` is used to construct the RefactorProposal for each tick;
/// the runner increments the id each tick.
pub async fn run_agent(
    ir: &mut SystemState, layout: &mut FileTopology, graph: &mut AgentGraph, proposal_seed: RefactorProposal, config: &RunnerConfig, bridge: &WsBridge,
) -> Result<Vec<TickStats>, RunnerError> {
    let mut ledger = NodeRewardLedger::new(config.ledger_alpha, config.base_trust_threshold);
    let mut stats: Vec<TickStats> = Vec::new();
    let mut tick_number: u64 = 0;
    // clean mode
    bridge.wait_for_connection().await;
    // clean mode
    loop {
        tick_number += 1;
        if config.max_ticks > 0 && tick_number > config.max_ticks {
            break;
        }
        eprintln!("[runner] tick {tick_number} — dispatching {} nodes", graph.nodes.len());
        let mut tick_stats = TickStats { tick_number, nodes_called: 0, llm_errors: 0, pipeline_reward: None, pipeline_error: None, meta_tick_fired: false, policy_updated: false };
        let mut dispatcher = AgentScheduler::new(graph, ir).with_trust_threshold(config.base_trust_threshold);
        let order = dispatcher.topological_call_order().map_err(RunnerError::Dispatch)?;
        let mut stage_outputs: Vec<AgentCallOutput> = Vec::new();
        for node_id in &order {
            let input = match dispatcher.dispatch(node_id) {
                Ok(inp) => inp,
                Err(e) => {
                    eprintln!("[runner] dispatch skip {node_id}: {e}");
                    continue;
                }
            };
            eprintln!("[runner]   → calling node {node_id} (stage={:?})", input.stage);
            match call_llm(bridge, &input, &config.chatgpt_url).await {
                Ok(output) => {
                    eprintln!("[runner]   ✓ node {node_id} responded");
                    tick_stats.nodes_called += 1;
                    stage_outputs.push(output.clone());
                    dispatcher.record_output(output);
                }
                Err(e) => {
                    eprintln!("[runner]   ✗ node {node_id} llm error: {e}");
                    tick_stats.llm_errors += 1;
                }
            }
        }
        if stage_outputs.is_empty() {
            eprintln!("[runner] tick {tick_number} — no outputs, skipping pipeline");
            stats.push(tick_stats);
            continue;
        }
        let mut proposal = proposal_seed.clone();
        proposal.id = format!("{}-tick-{}", proposal_seed.id, tick_number);
        let pipeline_result = run_refactor_pipeline(ir, layout, proposal, &stage_outputs);
        let primary_node = order.first().map(|s| s.as_str()).unwrap_or("unknown");
        let _threshold = record_refactor_reward(&mut ledger, primary_node, pipeline_result.as_ref());
        match &pipeline_result {
            Ok(result) => {
                eprintln!("[runner] tick {tick_number} — pipeline OK reward={:.4} admission={}", result.reward, result.admission_id);
                tick_stats.pipeline_reward = Some(result.reward);
                *ir = result.ir.clone();
                *layout = result.layout.clone();
                match execute_deltas(&result.code_deltas, &config.workspace) {
                    Ok(()) => {
                        eprintln!("[runner] tick {tick_number} — deltas applied, cargo check passed");
                        write_ir_to_disk(ir, &config.ir_out)?;
                    }
                    Err(ExecutorError::StashDropFailed(e)) => {
                        // Non-fatal — changes are on disk, stash cleanup just failed.
                        eprintln!("[runner] tick {tick_number} — stash drop failed (non-fatal): {e}");
                        write_ir_to_disk(ir, &config.ir_out)?;
                    }
                    Err(e) => {
                        // Tree has been restored by executor. Roll back IR promotion too.
                        eprintln!("[runner] tick {tick_number} — executor failed, IR rolled back: {e}");
                        *ir = result.ir.clone(); // already promoted above, re-assign original
                        tick_stats.pipeline_error = Some(e.to_string());
                    }
                }
            }
            Err(super::pipelines::refactor::RefactorError::StageSkipped { stage }) => {
                eprintln!("[runner] tick {tick_number} — pipeline incomplete: stage {stage} skipped (trust building)");
            }
            Err(e) => {
                eprintln!("[runner] tick {tick_number} — pipeline error: {e}");
                tick_stats.pipeline_error = Some(e.to_string());
            }
        }
        if config.meta_tick_interval > 0 && tick_number % config.meta_tick_interval == 0 {
            tick_stats.meta_tick_fired = true;
            match evolve_capability_graph(graph, &ledger) {
                Ok(result) => {
                    eprintln!("[runner] meta-tick fired — applied={} rejected={} H={:.4}→{:.4}", result.applied.len(), result.rejected.len(), result.entropy_before, result.entropy_after,);
                    *graph = result.graph;
                    save_capability_graph(graph, &config.graph_out).map_err(|e| RunnerError::Io(e.to_string()))?;
                }
                Err(crate::meta::GraphEvolutionError::NothingToDo) => {
                    eprintln!("[runner] meta-tick — nothing to do");
                }
                Err(e) => {
                    eprintln!("[runner] meta-tick error: {e}");
                }
            }
        }
        if config.policy_update_interval > 0 && tick_number % config.policy_update_interval == 0 {
            if let Some(current_policy) = ir.policy_parameters.last() {
                match ledger.update_policy(current_policy) {
                    Ok(new_policy) => {
                        eprintln!("[runner] policy updated — lr={:.4} baseline={:.4}", new_policy.learning_rate, new_policy.reward_baseline);
                        ir.policy_parameters.push(new_policy);
                        tick_stats.policy_updated = true;
                    }
                    Err(e) => {
                        eprintln!("[runner] policy update error: {e:?}");
                    }
                }
            }
        }
        write_ledger_to_disk(&ledger, &config.ledger_out)?;
        stats.push(tick_stats);
    }
    Ok(stats)
}
fn write_ir_to_disk(ir: &SystemState, path: &Path) -> Result<(), RunnerError> {
    let json = serde_json::to_string_pretty(ir).map_err(|e| RunnerError::Io(e.to_string()))?;
    fs::write(path, json).map_err(|e| RunnerError::Io(e.to_string()))
}
fn write_ledger_to_disk(ledger: &NodeRewardLedger, path: &Path) -> Result<(), RunnerError> {
    let json = serde_json::to_string_pretty(ledger).map_err(|e| RunnerError::Io(e.to_string()))?;
    fs::write(path, json).map_err(|e| RunnerError::Io(e.to_string()))
}

//! IR slice builder — extracts a typed CanonicalIr subset per IrField declaration.
//!
//! This is the enforcement mechanism for stateless call safety.
//! A node literally cannot see fields it did not declare in CapabilityNode::reads.
use super::capability::IrField;
use crate::ir::SystemState;
use serde_json::{Map, Value};
/// Maximum number of items to include per list field in a slice.
/// Keeps prompts within LLM context limits.
const MAX_LIST_ITEMS: usize = 30;
/// Truncate a JSON array to MAX_LIST_ITEMS, appending a sentinel if clipped.
fn truncate_list(v: Value) -> Value {
    match v {
        Value::Array(mut arr) => {
            let total = arr.len();
            arr.truncate(MAX_LIST_ITEMS);
            if total > MAX_LIST_ITEMS {
                arr.push(Value::String(format!("... ({} more items truncated)", total - MAX_LIST_ITEMS)));
            }
            Value::Array(arr)
        }
        other => other,
    }
}
/// Strip heavy fields from a Function object before sending to the LLM.
/// Removes large payloads (e.g., bytecode, AST) and keeps structural data only.
fn slim_function(f: &crate::ir::Function) -> Value {
    serde_json::json!(
        { "id" : f.id, "name" : f.name, "module" : f.module, "visibility" : f.visibility,
        "inputs" : f.inputs, "outputs" : f.outputs, "deltas" : f.deltas, }
    )
}
/// Builds a JSON object containing only the IR fields listed in `fields`.
/// The returned Value is what gets handed to AgentCallInput::ir_slice.
pub fn slice_ir_fields(ir: &SystemState, fields: &[IrField]) -> Value {
    let mut map = Map::new();
    for field in fields {
        let (key, value) = extract_field(ir, field);
        map.insert(key, value);
    }
    Value::Object(map)
}
/// Extracts a single IrField from CanonicalIr as a (key, JSON value) pair.
fn extract_field(ir: &SystemState, field: &IrField) -> (String, Value) {
    match field {
        IrField::Modules => ("modules".into(), truncate_list(serde_json::to_value(&ir.modules).unwrap_or(Value::Null))),
        IrField::ModuleEdges => ("module_edges".into(), truncate_list(serde_json::to_value(&ir.module_edges).unwrap_or(Value::Null))),
        IrField::Structs => ("structs".into(), truncate_list(serde_json::to_value(&ir.structs).unwrap_or(Value::Null))),
        IrField::Enums => ("enums".into(), truncate_list(serde_json::to_value(&ir.enums).unwrap_or(Value::Null))),
        IrField::Traits => ("traits".into(), truncate_list(serde_json::to_value(&ir.traits).unwrap_or(Value::Null))),
        IrField::ImplBlocks => ("impls".into(), truncate_list(serde_json::to_value(&ir.impls).unwrap_or(Value::Null))),
        IrField::Functions => ("functions".into(), truncate_list(Value::Array(ir.functions.iter().map(slim_function).collect()))),
        IrField::CallEdges => ("call_edges".into(), truncate_list(serde_json::to_value(&ir.call_edges).unwrap_or(Value::Null))),
        IrField::TickGraphs => ("tick_graphs".into(), truncate_list(serde_json::to_value(&ir.tick_graphs).unwrap_or(Value::Null))),
        IrField::SystemGraphs => ("system_graphs".into(), truncate_list(serde_json::to_value(&ir.system_graphs).unwrap_or(Value::Null))),
        IrField::LoopPolicies => ("loop_policies".into(), truncate_list(serde_json::to_value(&ir.loop_policies).unwrap_or(Value::Null))),
        IrField::Ticks => ("ticks".into(), truncate_list(serde_json::to_value(&ir.ticks).unwrap_or(Value::Null))),
        IrField::TickEpochs => ("tick_epochs".into(), truncate_list(serde_json::to_value(&ir.tick_epochs).unwrap_or(Value::Null))),
        IrField::PolicyParameters => ("policy_parameters".into(), truncate_list(serde_json::to_value(&ir.policy_parameters).unwrap_or(Value::Null))),
        IrField::Plans => ("plans".into(), truncate_list(serde_json::to_value(&ir.plans).unwrap_or(Value::Null))),
        IrField::Executions => ("executions".into(), truncate_list(serde_json::to_value(&ir.executions).unwrap_or(Value::Null))),
        IrField::Admissions => ("admissions".into(), truncate_list(serde_json::to_value(&ir.admissions).unwrap_or(Value::Null))),
        IrField::AppliedDeltas => ("applied_deltas".into(), truncate_list(serde_json::to_value(&ir.applied_deltas).unwrap_or(Value::Null))),
        IrField::GpuFunctions => ("gpu_functions".into(), truncate_list(serde_json::to_value(&ir.gpu_functions).unwrap_or(Value::Null))),
        IrField::Proposals => ("proposals".into(), truncate_list(serde_json::to_value(&ir.proposals).unwrap_or(Value::Null))),
        IrField::Judgments => ("judgments".into(), truncate_list(serde_json::to_value(&ir.judgments).unwrap_or(Value::Null))),
        IrField::JudgmentPredicates => ("judgment_predicates".into(), truncate_list(serde_json::to_value(&ir.judgment_predicates).unwrap_or(Value::Null))),
        IrField::Deltas => ("deltas".into(), truncate_list(serde_json::to_value(&ir.deltas).unwrap_or(Value::Null))),
        IrField::Proofs => ("proofs".into(), truncate_list(serde_json::to_value(&ir.proofs).unwrap_or(Value::Null))),
        IrField::Learning => ("learning".into(), truncate_list(serde_json::to_value(&ir.learning).unwrap_or(Value::Null))),
        IrField::Errors => ("errors".into(), truncate_list(serde_json::to_value(&ir.errors).unwrap_or(Value::Null))),
        IrField::Dependencies => ("dependencies".into(), truncate_list(serde_json::to_value(&ir.dependencies).unwrap_or(Value::Null))),
        IrField::FileHashes => ("file_hashes".into(), truncate_list(serde_json::to_value(&ir.file_hashes).unwrap_or(Value::Null))),
        IrField::RewardDeltas => ("reward_deltas".into(), truncate_list(serde_json::to_value(&ir.reward_deltas).unwrap_or(Value::Null))),
        IrField::WorldModel => ("world_model".into(), truncate_list(serde_json::to_value(&ir.world_model).unwrap_or(Value::Null))),
        IrField::GoalMutations => ("goal_mutations".into(), truncate_list(serde_json::to_value(&ir.goal_mutations).unwrap_or(Value::Null))),
    }
}

//! WebSocket server — bridges the Chrome extension to the agent.
//!
//! Architecture:
//!   - Single shared WS connection from the extension (one background.js).
//!   - All messages tagged with tabId.
//!
//! Extension → Rust frames:
//!   { "type": "TAB_OPENED",     "tabId": n, "url": "...", "reqId"?: n }
//!   { "type": "TAB_CLOSED",     "tabId": n }
//!   { "type": "TAB_READY",      "tabId": n, "url": "...", "reqId"?: n }
//!   { "type": "INBOUND_MESSAGE","tabId": n, "payload": "..." }
//!   { "type": "PING" }                          ← keepalive, ignored
//!
//! Rust → Extension frames:
//!   { "type": "OPEN_TAB",       "url": "...", "reqId"?: n }
//!   { "type": "TURN",           "tabId": n, "text": "...", "turnId"?: n }
//!   { "type": "OUTBOUND_SUBMIT","tabId": n, "payload": { ... } }
//!   { "type": "CLOSE_TAB",      "tabId": n }
//!   { "type": "NEW_CHAT",       "tabId": n }
//!   { "type": "TEMP_CHAT",      "tabId": n }
//!
//! WsBridge is a cheap-clone handle for callers.

use std::collections::HashMap;
use std::fs;
use std::io::Write;
use std::net::SocketAddr;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;

use super::parsers::{FrameAssembler, SiteType};
use futures_util::{SinkExt, StreamExt};
use serde_json::{json, Value};
use tokio::net::{TcpListener, TcpStream};
use tokio::sync::{mpsc, oneshot, Mutex};
use tokio_tungstenite::accept_async;
use tokio_tungstenite::tungstenite::Message;

fn append_jsonl(path: &str, value: &Value) {
    if let Ok(mut file) = fs::OpenOptions::new().create(true).append(true).open(path) {
        if let Ok(line) = serde_json::to_string(value) {
            let _ = writeln!(file, "{}", line);
        }
    }
}

// ---------------------------------------------------------------------------
// Public error type
// ---------------------------------------------------------------------------

#[derive(Debug)]
pub enum WsBridgeError {
    NotConnected,
    NoTab,
    Timeout,
    Cancelled,
}

impl std::fmt::Display for WsBridgeError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            WsBridgeError::NotConnected => write!(f, "extension not connected"),
            WsBridgeError::NoTab => write!(f, "no live ChatGPT tab"),
            WsBridgeError::Timeout => write!(f, "timeout waiting for ChatGPT response"),
            WsBridgeError::Cancelled => write!(f, "response channel cancelled"),
        }
    }
}

impl std::error::Error for WsBridgeError {}

// ---------------------------------------------------------------------------
// Server state
// ---------------------------------------------------------------------------

struct ServerState {
    /// Outbound channel to the single extension WS connection.
    /// None when the extension is not connected.
    out_tx: Option<mpsc::Sender<Message>>,

    /// tabId → frame assembler (parser + buffering).
    tab_assemblers: HashMap<u32, FrameAssembler>,

    /// tabId → oneshot waiting for a completed response.
    pending: HashMap<u32, oneshot::Sender<String>>,
    /// tabId → expected turnId for inbound chunk filtering.
    pending_turn_id: HashMap<u32, u64>,

    /// reqId → oneshot waiting for TAB_OPENED confirmation.
    pending_open: HashMap<u64, oneshot::Sender<u32>>,
    /// tabId → oneshot waiting for NEW_CHAT completion.
    pending_new_chat: HashMap<u32, oneshot::Sender<()>>,
    /// tabId → oneshot waiting for TEMP_CHAT completion.
    pending_temp_chat: HashMap<u32, oneshot::Sender<()>>,

    /// All live tabs reported by the extension.
    live_tabs: std::collections::HashSet<u32>,

    /// TURN frames buffered while the extension WS is disconnected.
    /// Drained into out_tx the moment a new connection is established,
    /// so no TURN is silently dropped during a reconnect window.
    turn_replay_queue: Vec<Value>,

    /// Monotonic counter for frame dump filenames.
    frame_counter: u64,
}

impl ServerState {
    fn new() -> Self {
        // Prepare clean frame dump directory
        let dump_dir = "./frames";
        let _ = fs::create_dir_all(dump_dir);
        if let Ok(entries) = fs::read_dir(dump_dir) {
            for entry in entries.flatten() {
                let _ = fs::remove_file(entry.path());
            }
        }

        Self {
            out_tx: None,
            tab_assemblers: HashMap::new(),
            pending: HashMap::new(),
            pending_turn_id: HashMap::new(),
            pending_open: HashMap::new(),
            pending_new_chat: HashMap::new(),
            pending_temp_chat: HashMap::new(),
            live_tabs: std::collections::HashSet::new(),
            turn_replay_queue: Vec::new(),
            frame_counter: 0,
        }
    }

    fn send(&self, msg: Value) -> Result<(), WsBridgeError> {
        let tx = self.out_tx.as_ref().ok_or(WsBridgeError::NotConnected)?;
        let raw = msg.to_string();
        match tx.try_send(Message::Text(raw.into())) {
            Ok(()) => Ok(()),
            Err(e) => Err(WsBridgeError::NotConnected),
        }
    }
}

// ---------------------------------------------------------------------------
// Public bridge handle
// ---------------------------------------------------------------------------

#[derive(Clone)]
pub struct WsBridge {
    state: Arc<Mutex<ServerState>>,
    next_req_id: Arc<AtomicU64>,
    next_turn_id: Arc<AtomicU64>,
    response_timeout_secs: u64,
}

impl WsBridge {
    /// Open a new tab at `url` and return its tabId once the extension confirms.
    pub async fn open_fresh_tab_with_url(&self, url: String) -> Result<u32, WsBridgeError> {
        let req_id = self.next_req_id.fetch_add(1, Ordering::Relaxed);
        let (tx, rx) = oneshot::channel::<u32>();

        {
            let mut st = self.state.lock().await;
            st.pending_open.insert(req_id, tx);
            st.send(json!({ "type": "OPEN_TAB", "url": url, "reqId": req_id }))?;
        }

        rx.await.map_err(|_| WsBridgeError::Cancelled)
    }

    /// Send a TURN to `tab_id` and wait for the assembled response.
    ///
    /// If the WS is live the frame is sent immediately.
    /// If the WS is disconnected the frame is pushed into `turn_replay_queue`
    /// and will be replayed the moment the extension reconnects, so no TURN
    /// is silently lost during the ~1 s reconnect window.
    pub async fn send_turn(&self, tab_id: u32, text: String) -> Result<String, WsBridgeError> {
        let (tx, rx) = oneshot::channel::<String>();
        let turn_id = self.next_turn_id.fetch_add(1, Ordering::Relaxed);

        {
            let mut st = self.state.lock().await;
            st.pending.insert(tab_id, tx);
            st.pending_turn_id.insert(tab_id, turn_id);
            if !st.tab_assemblers.contains_key(&tab_id) {
                st.tab_assemblers.insert(tab_id, FrameAssembler::new(SiteType::Unknown));
            } else if let Some(asm) = st.tab_assemblers.get_mut(&tab_id) {
                asm.reset();
            }

            let frame = json!({ "type": "TURN", "tabId": tab_id, "text": text, "turnId": turn_id });

            match st.send(frame.clone()) {
                Ok(()) => {}
                Err(_) => {
                    // Socket is down — buffer the frame for replay on reconnect.
                    st.turn_replay_queue.push(frame);
                }
            }
        }

        match tokio::time::timeout(std::time::Duration::from_secs(self.response_timeout_secs), rx).await {
            Ok(Ok(text)) => Ok(text),
            Ok(Err(_)) => Err(WsBridgeError::Cancelled),
            Err(_) => Err(WsBridgeError::Timeout),
        }
    }

    /// Block until the extension WS is connected.
    pub async fn wait_for_connection(&self) {
        loop {
            {
                let st = self.state.lock().await;
                if st.out_tx.is_some() {
                    return;
                }
            }
            tokio::time::sleep(std::time::Duration::from_millis(200)).await;
        }
    }

    /// Send an OUTBOUND_SUBMIT directly to a tab (Rust-driven injection).
    pub async fn outbound_submit(&self, tab_id: u32, payload: Value) -> Result<(), WsBridgeError> {
        let st = self.state.lock().await;
        st.send(json!({ "type": "OUTBOUND_SUBMIT", "tabId": tab_id, "payload": payload }))
    }

    /// Close a tab by id.
    pub async fn close_tab(&self, tab_id: u32) -> Result<(), WsBridgeError> {
        let st = self.state.lock().await;
        st.send(json!({ "type": "CLOSE_TAB", "tabId": tab_id }))
    }

    /// Trigger a new chat in the tab.
    pub async fn new_chat(&self, tab_id: u32) -> Result<(), WsBridgeError> {
        let st = self.state.lock().await;
        st.send(json!({ "type": "NEW_CHAT", "tabId": tab_id }))
    }

    /// Trigger temporary chat in the tab (ChatGPT).
    pub async fn temp_chat(&self, tab_id: u32) -> Result<(), WsBridgeError> {
        let st = self.state.lock().await;
        st.send(json!({ "type": "TEMP_CHAT", "tabId": tab_id }))
    }

    /// Wait for NEW_CHAT completion signal from the tab.
    pub async fn wait_new_chat(&self, tab_id: u32, timeout_secs: u64) -> Result<(), WsBridgeError> {
        let (tx, rx) = oneshot::channel::<()>();
        {
            let mut st = self.state.lock().await;
            st.pending_new_chat.insert(tab_id, tx);
        }
        match tokio::time::timeout(std::time::Duration::from_secs(timeout_secs), rx).await {
            Ok(Ok(())) => Ok(()),
            Ok(Err(_)) => Err(WsBridgeError::Cancelled),
            Err(_) => Err(WsBridgeError::Timeout),
        }
    }

    /// Wait for TEMP_CHAT completion signal from the tab.
    pub async fn wait_temp_chat(&self, tab_id: u32, timeout_secs: u64) -> Result<(), WsBridgeError> {
        let (tx, rx) = oneshot::channel::<()>();
        {
            let mut st = self.state.lock().await;
            st.pending_temp_chat.insert(tab_id, tx);
        }
        match tokio::time::timeout(std::time::Duration::from_secs(timeout_secs), rx).await {
            Ok(Ok(())) => Ok(()),
            Ok(Err(_)) => Err(WsBridgeError::Cancelled),
            Err(_) => Err(WsBridgeError::Timeout),
        }
    }
}

// ---------------------------------------------------------------------------
// Server bootstrap
// ---------------------------------------------------------------------------

pub fn spawn(addr: SocketAddr, response_timeout_secs: u64) -> WsBridge {
    let state = Arc::new(Mutex::new(ServerState::new()));
    let bridge = WsBridge { state: state.clone(), next_req_id: Arc::new(AtomicU64::new(1)), next_turn_id: Arc::new(AtomicU64::new(1)), response_timeout_secs };

    tokio::spawn(async move {
        loop {
            match TcpListener::bind(addr).await {
                Ok(listener) => {
                    accept_loop(listener, state.clone()).await;
                }
                Err(e) => {
                    tokio::time::sleep(std::time::Duration::from_secs(2)).await;
                }
            }
        }
    });

    bridge
}

async fn accept_loop(listener: TcpListener, state: Arc<Mutex<ServerState>>) {
    loop {
        match listener.accept().await {
            Ok((stream, peer)) => {
                handle_connection(stream, state.clone()).await;
            }
            Err(_e) => {}
        }
    }
}

async fn handle_connection(stream: TcpStream, state: Arc<Mutex<ServerState>>) {
    let ws = match accept_async(stream).await {
        Ok(ws) => ws,
        Err(_e) => {
            return;
        }
    };

    let (mut sink, mut source) = ws.split();
    let (tx_out, mut rx_out) = mpsc::channel::<Message>(256);

    {
        let mut st = state.lock().await;
        st.out_tx = Some(tx_out.clone());

        // Drain any TURN frames that were buffered while the socket was down.
        let queued: Vec<Value> = st.turn_replay_queue.drain(..).collect();
        if !queued.is_empty() {
            for frame in queued {
                let _ = tx_out.try_send(Message::Text(frame.to_string().into()));
            }
        }
    }

    let sink_task = tokio::spawn(async move {
        while let Some(msg) = rx_out.recv().await {
            match sink.send(msg).await {
                Ok(()) => {}
                Err(_e) => {
                    break;
                }
            }
        }
    });

    while let Some(result) = source.next().await {
        match result {
            Ok(Message::Text(text)) => handle_inbound(text.as_str(), &state).await,
            Ok(Message::Close(_)) | Err(_) => break,
            _ => {}
        }
    }

    sink_task.abort();

    {
        let mut st = state.lock().await;
        st.out_tx = None;
    }
}

// ---------------------------------------------------------------------------
// Inbound frame handler
// ---------------------------------------------------------------------------

async fn handle_inbound(raw: &str, state: &Arc<Mutex<ServerState>>) {
    let msg: Value = match serde_json::from_str(raw) {
        Ok(v) => v,
        Err(_) => {
            return;
        }
    };

    let msg_type = msg.get("type").and_then(|v| v.as_str()).unwrap_or("");

    match msg_type {
        // Keepalive from background.js — no state change needed.
        "PING" => {}

        "TAB_OPENED" => {
            let tab_id = match msg.get("tabId").and_then(|v| v.as_u64()) {
                Some(id) => id as u32,
                None => return,
            };
            let url = msg.get("url").and_then(|v| v.as_str()).unwrap_or("");
            let mut st = state.lock().await;
            st.live_tabs.insert(tab_id);
            let site = SiteType::from_url(url);
            st.tab_assemblers.entry(tab_id).and_modify(|asm| asm.set_site(site)).or_insert_with(|| FrameAssembler::new(site));
        }

        "TAB_CLOSED" => {
            let tab_id = match msg.get("tabId").and_then(|v| v.as_u64()) {
                Some(id) => id as u32,
                None => return,
            };
            let mut st = state.lock().await;
            st.live_tabs.remove(&tab_id);
            st.tab_assemblers.remove(&tab_id);
            st.pending.remove(&tab_id);
            st.pending_turn_id.remove(&tab_id);
            st.pending_new_chat.remove(&tab_id);
        }

        "TAB_READY" => {
            let tab_id = match msg.get("tabId").and_then(|v| v.as_u64()) {
                Some(id) => id as u32,
                None => return,
            };
            let url = msg.get("url").and_then(|v| v.as_str()).unwrap_or("");
            let req_id = msg.get("reqId").and_then(|v| v.as_u64());

            let mut st = state.lock().await;
            let site = SiteType::from_url(url);
            st.tab_assemblers.entry(tab_id).and_modify(|asm| asm.set_site(site)).or_insert_with(|| FrameAssembler::new(site));

            if let Some(rid) = req_id {
                if let Some(tx) = st.pending_open.remove(&rid) {
                    let _ = tx.send(tab_id);
                }
            }
        }

        "INBOUND_MESSAGE" => {
            let tab_id = match msg.get("tabId").and_then(|v| v.as_u64()) {
                Some(id) => id as u32,
                None => return,
            };
            let payload = match msg.get("payload").and_then(|v| v.as_str()) {
                Some(s) => s.to_string(),
                None => return,
            };

            let mut st = state.lock().await;
            let mut inbound_turn_id: Option<u64> = None;
            let mut chunk = payload.clone();
            if payload.trim_start().starts_with('{') {
                if let Ok(v) = serde_json::from_str::<Value>(&payload) {
                    if let Some(c) = v.get("chunk").and_then(|v| v.as_str()) {
                        chunk = c.to_string();
                    }
                    if let Some(tid) = v.get("turn_id").and_then(|v| v.as_u64()) {
                        inbound_turn_id = Some(tid);
                    }
                }
            }

            let expected = st.pending_turn_id.get(&tab_id).copied();
            if let Some(tid) = inbound_turn_id {
                if expected != Some(tid) {
                    return;
                }
            } else if expected.is_some() {
                return;
            }

            // Dump every inbound frame to disk for parser inspection.
            st.frame_counter += 1;
            let inbound_record = json!({
                "frame_counter": st.frame_counter,
                "tab_id": tab_id,
                "turn_id": inbound_turn_id,
                "expected_turn_id": expected,
                "chunk": chunk,
            });
            append_jsonl("./frames/inbound.jsonl", &inbound_record);

            let assembled = if let Some(asm) = st.tab_assemblers.get_mut(&tab_id) {
                asm.push(&chunk)
            } else {
                let mut asm = FrameAssembler::new(SiteType::Unknown);
                let out = asm.push(&chunk);
                st.tab_assemblers.insert(tab_id, asm);
                out
            };

            if let Some(text) = assembled {
                // Dump assembled message for debugging (Gemini/ChatGPT).
                let assembled_record = json!({
                    "tab_id": tab_id,
                    "turn_id": inbound_turn_id.or(expected),
                    "text": text,
                });
                append_jsonl("./frames/assembled.jsonl", &assembled_record);
                if let Some(tx) = st.pending.remove(&tab_id) {
                    let _ = tx.send(text);
                }
                st.pending_turn_id.remove(&tab_id);
            }
        }

        "NEW_CHAT_DONE" => {
            let tab_id = match msg.get("tabId").and_then(|v| v.as_u64()) {
                Some(id) => id as u32,
                None => return,
            };
            eprintln!("[ws] NEW_CHAT_DONE tab={}", tab_id);
            let mut st = state.lock().await;
            if let Some(tx) = st.pending_new_chat.remove(&tab_id) {
                let _ = tx.send(());
            }
        }
        "TEMP_CHAT_DONE" => {
            let tab_id = match msg.get("tabId").and_then(|v| v.as_u64()) {
                Some(id) => id as u32,
                None => return,
            };
            eprintln!("[ws] TEMP_CHAT_DONE tab={}", tab_id);
            let mut st = state.lock().await;
            if let Some(tx) = st.pending_temp_chat.remove(&tab_id) {
                let _ = tx.send(());
            }
        }

        _other => {}
    }
}

use crate::call::AgentCallOutput;
use crate::io::{load_capability_graph, save_capability_graph};
use crate::ir::SystemState;
use crate::layout::FileTopology;
use crate::pipelines::refactor::{run_refactor_pipeline, RefactorProposal};
use crate::reward::NodeRewardLedger;

use std::error::Error;
use std::fs;
use std::path::Path;

/// Minimal orchestration surface for canon-agent.
/// This intentionally excludes kernel, GPU, ingest,
/// DSL auto-application, and other monolith features.

pub enum AgentCommand {
    RunPipeline { ir: SystemState, layout: FileTopology, proposal: RefactorProposal, stage_outputs: Vec<AgentCallOutput> },
    MetaTick { graph_path: String, ledger_path: String, output_graph: String },
    ShowLedger { ledger_path: String },
    ShowGraph { graph_path: String },
}

pub async fn execute_agent_command(cmd: AgentCommand) -> Result<(), Box<dyn Error>> {
    match cmd {
        AgentCommand::RunPipeline { ir, layout, proposal, stage_outputs } => {
            let result = run_refactor_pipeline(&ir, &layout, proposal, &stage_outputs)?;

            println!("Pipeline OK — reward={:.4}  admission={}", result.reward, result.admission_id);
        }

        AgentCommand::MetaTick { graph_path, ledger_path, output_graph } => {
            let cap_graph = load_capability_graph(Path::new(&graph_path))?;
            let ledger_doc: NodeRewardLedger = serde_json::from_slice(&fs::read(&ledger_path)?)?;

            let result = crate::meta::evolve_capability_graph(&cap_graph, &ledger_doc)?;

            println!("Meta-tick OK");
            println!("  entropy: {:.4} → {:.4}", result.entropy_before, result.entropy_after);
            println!("  applied mutations : {}", result.applied.len());
            println!("  rejected mutations: {}", result.rejected.len());

            save_capability_graph(&result.graph, Path::new(&output_graph))?;
        }

        AgentCommand::ShowLedger { ledger_path } => {
            let ledger_doc: NodeRewardLedger = serde_json::from_slice(&fs::read(&ledger_path)?)?;

            let ranked = ledger_doc.ranked_nodes();

            println!("{:<30} {:>10} {:>10}", "node_id", "ema_reward", "run_count");
            println!("{}", "-".repeat(54));

            for entry in ranked {
                println!("{:<30} {:>10.4} {:>10}", entry.node_id, entry.ema_reward, entry.run_count);
            }

            println!("aggregate reward: {:.4}", ledger_doc.aggregate_reward());
        }

        AgentCommand::ShowGraph { graph_path } => {
            let cap_graph = load_capability_graph(Path::new(&graph_path))?;

            println!("Capability graph: {} nodes, {} edges", cap_graph.nodes.len(), cap_graph.edges.len());
            println!("Entropy H(G) = {:.4}", cap_graph.entropy());

            println!("{:<20} {:<12} {}", "id", "kind", "label");
            println!("{}", "-".repeat(60));

            for node in &cap_graph.nodes {
                println!("{:<20} {:<12} {}", node.id, format!("{:?}", node.kind), node.label);
            }
        }
    }

    Ok(())
}

use crate::ir::CodeDelta;

pub fn emit_shell(deltas: &[CodeDelta]) -> String {
    let mut out = String::new();

    for d in deltas {
        match d {
            CodeDelta::ApplyPatch { patch } => {
                out.push_str("apply_patch << 'EOF'\n");
                out.push_str(patch);
                out.push_str("\nEOF\n\n");
            }
            CodeDelta::Bash { command } | CodeDelta::BashReadOnly { command } => {
                out.push_str(command);
                out.push('\n');
            }
        }
    }

    out
}

pub mod lyapunov;
mod structural;
use crate::ir::{ChangePayload, CodeDelta, DeltaId, SystemState, Visibility};
pub use lyapunov::{enforce_lyapunov_bound, StructureDriftError, StructureMetrics, DEFAULT_TOPOLOGY_THETA};
use thiserror::Error;

#[derive(Debug, Error)]
pub enum EvolutionError {
    #[error("struct `{0}` does not exist")]
    UnknownStruct(String),
    #[error("function `{0}` does not exist")]
    UnknownFunction(String),
    #[error("trait `{0}` does not exist")]
    UnknownTrait(String),
    #[error("trait function `{0}` does not exist")]
    UnknownTraitFunction(String),
    #[error("module `{0}` does not exist")]
    UnknownModule(String),
    #[error("impl `{0}` does not exist")]
    UnknownImpl(String),
    #[error("execution `{0}` does not exist")]
    UnknownExecution(String),
    #[error("enum `{0}` does not exist")]
    UnknownEnum(String),
    #[error("unknown delta `{0}`")]
    UnknownDelta(DeltaId),
    #[error("artifact `{0}` already exists")]
    DuplicateArtifact(String),
    #[error("field `{field}` does not exist on struct `{struct_id}`")]
    UnknownField { struct_id: String, field: String },
    #[error("topology drift rejected: {0}")]
    TopologyDrift(StructureDriftError),
}

// π: module_id → src/<module_id>.rs
fn module_path(module_id: &str) -> String {
    format!("src/{}.rs", module_id)
}

fn vis_str(v: Visibility) -> &'static str {
    match v {
        Visibility::Public => "pub ",
        Visibility::PubCrate => "pub(crate) ",
        Visibility::PubSuper => "pub(super) ",
        Visibility::Private => "",
    }
}

// φ: ChangePayload → CodeDelta::ApplyPatch (or Bash no-op for non-file variants)
fn payload_to_code_delta(payload: &ChangePayload) -> CodeDelta {
    match payload {
        // ── AddModule: create new file with module stub ────────────────────────
        ChangePayload::AddModule { module_id, name, visibility, description } => {
            let vis = vis_str(*visibility);
            let patch = format!(
                "*** Begin Patch\n\
                 *** Add File: {path}\n\
                 +// {desc}\n\
                 +{vis}mod {name} {{}}\n\
                 *** End Patch\n",
                path = module_path(module_id),
                desc = description,
                vis  = vis,
                name = name.as_str(),
            );
            CodeDelta::ApplyPatch { patch }
        }

        // ── AddStruct: append struct definition to module file ─────────────────
        ChangePayload::AddStruct { module, struct_id: _, name } => {
            let path = module_path(module);
            let patch = format!(
                "*** Begin Patch\n\
                 *** Update File: {path}\n\
                 @@\n\
                 +\n\
                 +pub struct {name} {{\n\
                 +}}\n\
                 *** End Patch\n",
                path = path,
                name = name.as_str(),
            );
            CodeDelta::ApplyPatch { patch }
        }

        // ── AddField: append field to struct block ─────────────────────────────
        ChangePayload::AddField { struct_id, field } => {
            // Target the module that owns this struct; we don't have a direct
            // module→file mapping without the IR here, so we use struct_id as
            // the file key by convention (struct_id is "<module>::<name>").
            let module_hint = struct_id.split("::").next().unwrap_or(struct_id.as_str());
            let path = module_path(module_hint);
            let patch = format!(
                "*** Begin Patch\n\
                 *** Update File: {path}\n\
                 @@\n\
                 +    pub {field_name}: (),\n\
                 *** End Patch\n",
                path       = path,
                field_name = field.name.as_str(),
            );
            CodeDelta::ApplyPatch { patch }
        }

        // ── AddTrait: append trait skeleton to module file ─────────────────────
        ChangePayload::AddTrait { module, trait_id: _, name } => {
            let path = module_path(module);
            let patch = format!(
                "*** Begin Patch\n\
                 *** Update File: {path}\n\
                 @@\n\
                 +\n\
                 +pub trait {name} {{\n\
                 +}}\n\
                 *** End Patch\n",
                path = path,
                name = name.as_str(),
            );
            CodeDelta::ApplyPatch { patch }
        }

        // ── AddTraitFunction: append fn signature inside trait ─────────────────
        ChangePayload::AddTraitFunction { trait_id, function } => {
            let module_hint = trait_id.split("::").next().unwrap_or(trait_id.as_str());
            let path = module_path(module_hint);
            let patch = format!(
                "*** Begin Patch\n\
                 *** Update File: {path}\n\
                 @@\n\
                 +    fn {name}(&self);\n\
                 *** End Patch\n",
                path = path,
                name = function.name.as_str(),
            );
            CodeDelta::ApplyPatch { patch }
        }

        // ── AddImpl: append impl block skeleton ───────────────────────────────
        ChangePayload::AddImpl { module, impl_id: _, struct_id, trait_id } => {
            let path = module_path(module);
            let struct_name = struct_id.split("::").last().unwrap_or(struct_id.as_str());
            let trait_name  = trait_id.split("::").last().unwrap_or(trait_id.as_str());
            let patch = format!(
                "*** Begin Patch\n\
                 *** Update File: {path}\n\
                 @@\n\
                 +\n\
                 +impl {trait_name} for {struct_name} {{\n\
                 +}}\n\
                 *** End Patch\n",
                path        = path,
                trait_name  = trait_name,
                struct_name = struct_name,
            );
            CodeDelta::ApplyPatch { patch }
        }

        // ── AddFunction: append fn stub inside impl file ──────────────────────
        ChangePayload::AddFunction { function_id: _, impl_id, signature } => {
            let module_hint = impl_id.split("::").next().unwrap_or(impl_id.as_str());
            let path = module_path(module_hint);
            let vis  = vis_str(signature.visibility);
            let name = signature.name.as_str();
            let patch = format!(
                "*** Begin Patch\n\
                 *** Update File: {path}\n\
                 @@\n\
                 +    {vis}fn {name}(&self) {{\n\
                 +        todo!()\n\
                 +    }}\n\
                 *** End Patch\n",
                path = path,
                vis  = vis,
                name = name,
            );
            CodeDelta::ApplyPatch { patch }
        }

        // ── AddEnum: append enum skeleton ─────────────────────────────────────
        ChangePayload::AddEnum { module, enum_id: _, name, visibility } => {
            let vis  = vis_str(*visibility);
            let path = module_path(module);
            let patch = format!(
                "*** Begin Patch\n\
                 *** Update File: {path}\n\
                 @@\n\
                 +\n\
                 +{vis}enum {name} {{\n\
                 +}}\n\
                 *** End Patch\n",
                path = path,
                vis  = vis,
                name = name.as_str(),
            );
            CodeDelta::ApplyPatch { patch }
        }

        // ── AddEnumVariant: append variant to enum ────────────────────────────
        ChangePayload::AddEnumVariant { enum_id, variant } => {
            let module_hint = enum_id.split("::").next().unwrap_or(enum_id.as_str());
            let path = module_path(module_hint);
            let patch = format!(
                "*** Begin Patch\n\
                 *** Update File: {path}\n\
                 @@\n\
                 +    {variant},\n\
                 *** End Patch\n",
                path    = path,
                variant = variant.name.as_str(),
            );
            CodeDelta::ApplyPatch { patch }
        }

        // ── UpdateStructVisibility: patch pub keyword on struct line ───────────
        ChangePayload::UpdateStructVisibility { struct_id, visibility } => {
            let module_hint = struct_id.split("::").next().unwrap_or(struct_id.as_str());
            let struct_name = struct_id.split("::").last().unwrap_or(struct_id.as_str());
            let path    = module_path(module_hint);
            let new_vis = vis_str(*visibility);
            // Remove old visibility prefix lines, insert new one.
            let patch = format!(
                "*** Begin Patch\n\
                 *** Update File: {path}\n\
                 @@\n\
                 -struct {struct_name} {{\n\
                 +{new_vis}struct {struct_name} {{\n\
                 *** End Patch\n",
                path        = path,
                struct_name = struct_name,
                new_vis     = new_vis,
            );
            CodeDelta::ApplyPatch { patch }
        }

        // ── RemoveField: delete field line from struct ─────────────────────────
        ChangePayload::RemoveField { struct_id, field_name } => {
            let module_hint = struct_id.split("::").next().unwrap_or(struct_id.as_str());
            let path = module_path(module_hint);
            let patch = format!(
                "*** Begin Patch\n\
                 *** Update File: {path}\n\
                 @@\n\
                 -    pub {field_name}: (),\n\
                 *** End Patch\n",
                path       = path,
                field_name = field_name.as_str(),
            );
            CodeDelta::ApplyPatch { patch }
        }

        // ── RenameArtifact: sed-style rename via bash ─────────────────────────
        ChangePayload::RenameArtifact { kind, old_id, new_id } => {
            let old_name = old_id.split("::").last().unwrap_or(old_id.as_str());
            let new_name = new_id.split("::").last().unwrap_or(new_id.as_str());
            let module_hint = old_id.split("::").next().unwrap_or(old_id.as_str());
            let path = module_path(module_hint);
            let command = format!(
                "sed -i 's/\\b{old}\\b/{new}/g' {path}",
                old  = old_name,
                new  = new_name,
                path = path,
            );
            let _ = kind; // kind already drives rename_* in structural apply
            CodeDelta::Bash { command }
        }

        // ── UpdateFunctionAst / Inputs / Outputs: IR-only, no file delta ───────
        ChangePayload::UpdateFunctionAst { .. }
        | ChangePayload::UpdateFunctionInputs { .. }
        | ChangePayload::UpdateFunctionOutputs { .. }
        // ── Graph edges / events / rewards: no file mutation ──────────────────
        | ChangePayload::AddModuleEdge { .. }
        | ChangePayload::AddCallEdge { .. }
        | ChangePayload::AttachExecutionEvent { .. }
        | ChangePayload::RecordReward { .. } => {
            // No file mutation required; emit a no-op bash command so the
            // executor pipeline still gates on cargo check.
            CodeDelta::Bash { command: "true".to_string() }
        }
    }
}

pub fn apply_admitted_deltas(ir: &SystemState, admission_ids: &[String]) -> Result<(SystemState, Vec<CodeDelta>), EvolutionError> {
    let mut next = ir.clone();
    let mut code_deltas: Vec<CodeDelta> = Vec::new();

    for aid in admission_ids {
        // Look up the StateChange by id match.
        let delta = ir.deltas.iter().find(|d| &d.id == aid).ok_or_else(|| EvolutionError::UnknownDelta(aid.clone()))?;

        // Apply structural mutation to IR₁.
        structural::apply_structural_delta(&mut next, delta)?;

        // φ: emit CodeDelta from payload.
        if let Some(payload) = &delta.payload {
            code_deltas.push(payload_to_code_delta(payload));
        }
    }

    Ok((next, code_deltas))
}

//! Lyapunov stability gate for structural IR mutations.
//!
//! Before any structural delta mutates the IR topology, this gate checks
//! that the proposed change does not exceed the drift bound θ. This is the
//! safety invariant that makes self-modification controlled rather than arbitrary.
//!
//! Formally: ||Φ(G) - G||_F ≤ θ  →  mutation permitted
//!
//! We approximate the Frobenius norm over the adjacency matrix using
//! compute_goal_drift() over topology fingerprints (module + edge counts).
//! This keeps the gate purely data-structural — no LLM calls, no SMT.
use crate::ir::{
    goals::{compute_goal_drift, GoalDriftMetric},
    SystemState,
};
/// Default drift bound θ for structural mutations.
/// Tighter than goal mutation (0.05) — topology changes must be small per tick.
pub const DEFAULT_TOPOLOGY_THETA: f64 = 0.15;
/// A fingerprint of IR topology: used to compute drift between before/after.
#[derive(Debug, Clone)]
pub struct StructureMetrics {
    pub module_count: usize,
    pub module_edge_count: usize,
    pub struct_count: usize,
    pub trait_count: usize,
    pub function_count: usize,
    pub call_edge_count: usize,
    pub tick_graph_count: usize,
    pub delta_count: usize,
}
impl StructureMetrics {
    /// Captures the current IR topology.
    pub fn of(ir: &SystemState) -> Self {
        Self {
            module_count: ir.modules.len(),
            module_edge_count: ir.module_edges.len(),
            struct_count: ir.structs.len(),
            trait_count: ir.traits.len(),
            function_count: ir.functions.len(),
            call_edge_count: ir.call_edges.len(),
            tick_graph_count: ir.tick_graphs.len(),
            delta_count: ir.deltas.len(),
        }
    }
    /// Renders as a token string for drift computation.
    /// Each count is repeated as tokens so compute_goal_drift Jaccard distance
    /// reflects relative change in topology weight.
    pub fn as_token_string(&self) -> String {
        format!(
            "{} {} {} {} {} {} {} {}",
            "module ".repeat(self.module_count.max(1)),
            "module_edge ".repeat(self.module_edge_count.max(1)),
            "struct ".repeat(self.struct_count.max(1)),
            "trait ".repeat(self.trait_count.max(1)),
            "function ".repeat(self.function_count.max(1)),
            "call_edge ".repeat(self.call_edge_count.max(1)),
            "tick_graph ".repeat(self.tick_graph_count.max(1)),
            "delta ".repeat(self.delta_count.max(1)),
        )
    }
    /// Frobenius-approximated drift between two fingerprints.
    /// Uses the same Jaccard-based compute_goal_drift as goal mutation.
    pub fn drift_from(&self, other: &StructureMetrics, theta: f64) -> GoalDriftMetric {
        compute_goal_drift(&self.as_token_string(), &other.as_token_string(), theta)
    }
}
/// Error returned when the Lyapunov gate rejects a mutation.
#[derive(Debug, Clone)]
pub enum StructureDriftError {
    /// Topology drift exceeded bound θ.
    DriftExceeded { cosine_distance: f64, bound_theta: f64 },
    /// No invariant proofs were provided — gate requires at least one.
    NoInvariantProofs,
}
impl std::fmt::Display for StructureDriftError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            StructureDriftError::DriftExceeded { cosine_distance, bound_theta } => {
                write!(f, "topology drift {cosine_distance:.4} exceeds bound θ={bound_theta:.4}")
            }
            StructureDriftError::NoInvariantProofs => {
                write!(f, "structural mutation requires at least one invariant proof")
            }
        }
    }
}
impl std::error::Error for StructureDriftError {}
/// Gate a structural mutation by checking topology drift against θ.
///
/// Call this with the IR *before* and *after* a proposed mutation.
/// Returns Ok(GoalDriftMetric) if the mutation is within bound.
/// Returns Err(LyapunovError) if drift exceeds θ or proofs are missing.
///
/// # Arguments
/// - `before`         — IR snapshot before mutation
/// - `after`          — proposed IR after mutation
/// - `invariant_proof_ids` — proof ids that must be non-empty
/// - `theta`          — drift bound (use DEFAULT_TOPOLOGY_THETA if unsure)
pub fn enforce_lyapunov_bound(before: &SystemState, after: &SystemState, invariant_proof_ids: &[String], theta: f64) -> Result<GoalDriftMetric, StructureDriftError> {
    if invariant_proof_ids.is_empty() {
        return Err(StructureDriftError::NoInvariantProofs);
    }
    let fp_before = StructureMetrics::of(before);
    let fp_after = StructureMetrics::of(after);
    let mut metric = fp_before.drift_from(&fp_after, theta);
    metric.mutation_id = format!("topology:modules={}->{},functions={}->{}", fp_before.module_count, fp_after.module_count, fp_before.function_count, fp_after.function_count,);
    if !metric.within_bound {
        return Err(StructureDriftError::DriftExceeded { cosine_distance: metric.cosine_distance, bound_theta: theta });
    }
    Ok(metric)
}

