use super::super::EvolutionError;
use super::guard::*;
use super::rename::{rename_function, rename_module, rename_struct};
use crate::ir::{ChangePayload, ImplBlock, Module, ModuleEdge, Struct, StructKind, SystemState, Trait, Visibility};
pub fn apply_delta_payload(ir: &mut SystemState, payload: &ChangePayload, delta_id: &str) -> Result<(), EvolutionError> {
    match payload {
        ChangePayload::AddModule { module_id, name, visibility, description } => {
            if ir.modules.iter().any(|m| m.id == *module_id) {
                return Err(EvolutionError::DuplicateArtifact(module_id.clone()));
            }
            ir.modules.push(Module {
                id: module_id.clone(),
                name: name.clone(),
                visibility: *visibility,
                description: description.clone(),
                pub_uses: Vec::new(),
                constants: Vec::new(),
                type_aliases: Vec::new(),
                statics: Vec::new(),
                attributes: Vec::new(),
            });
        }
        ChangePayload::AddStruct { module, struct_id, name } => {
            if ir.structs.iter().any(|s| s.id == *struct_id) {
                return Err(EvolutionError::DuplicateArtifact(struct_id.clone()));
            }
            ensure_module_exists(ir, module)?;
            ir.structs.push(Struct {
                id: struct_id.clone(),
                name: name.clone(),
                module: module.clone(),
                visibility: Visibility::Private,
                derives: Vec::new(),
                doc: None,
                kind: StructKind::Normal,
                fields: vec![],
                history: vec![],
            });
        }
        ChangePayload::AddField { struct_id, field } => {
            let structure = ir.structs.iter_mut().find(|s| s.id == *struct_id).ok_or_else(|| EvolutionError::UnknownStruct(struct_id.clone()))?;
            if structure.fields.iter().any(|f| f.name == field.name) {
                return Err(EvolutionError::DuplicateArtifact(field.name.as_str().to_string()));
            }
            structure.fields.push(field.clone());
        }
        ChangePayload::UpdateStructVisibility { struct_id, visibility } => {
            let structure = ir.structs.iter_mut().find(|s| s.id == *struct_id).ok_or_else(|| EvolutionError::UnknownStruct(struct_id.clone()))?;
            structure.visibility = *visibility;
        }
        ChangePayload::RemoveField { struct_id, field_name } => {
            ensure_field_exists(ir, struct_id, field_name.as_str())?;
            if let Some(structure) = ir.structs.iter_mut().find(|s| s.id == *struct_id) {
                structure.fields.retain(|f| f.name.as_str() != field_name.as_str());
            }
        }
        ChangePayload::RenameArtifact { kind, old_id, new_id } => match kind.as_str() {
            "module" => rename_module(ir, old_id, new_id)?,
            "struct" => rename_struct(ir, old_id, new_id)?,
            "function" => rename_function(ir, old_id, new_id)?,
            _ => return Err(EvolutionError::UnknownDelta(delta_id.to_string())),
        },
        ChangePayload::AddTrait { module, trait_id, name } => {
            if ir.traits.iter().any(|t| t.id == *trait_id) {
                return Err(EvolutionError::DuplicateArtifact(trait_id.clone()));
            }
            ensure_module_exists(ir, module)?;
            ir.traits.push(Trait {
                id: trait_id.clone(),
                name: name.clone(),
                module: module.clone(),
                visibility: Visibility::Private,
                generic_params: Vec::new(),
                supertraits: Vec::new(),
                associated_types: Vec::new(),
                associated_consts: Vec::new(),
                functions: vec![],
            });
        }
        ChangePayload::AddTraitFunction { trait_id, function } => {
            let target_trait = ir.traits.iter_mut().find(|t| t.id == *trait_id).ok_or_else(|| EvolutionError::UnknownTrait(trait_id.clone()))?;
            if target_trait.functions.iter().any(|f| f.id == function.id) {
                return Err(EvolutionError::DuplicateArtifact(function.id.clone()));
            }
            target_trait.functions.push(function.clone());
        }
        ChangePayload::AddImpl { module, impl_id, struct_id, trait_id } => {
            if ir.impls.iter().any(|i| i.id == *impl_id) {
                return Err(EvolutionError::DuplicateArtifact(impl_id.clone()));
            }
            ensure_module_exists(ir, module)?;
            ensure_struct_exists(ir, struct_id)?;
            ensure_trait_exists(ir, trait_id)?;
            ir.impls.push(ImplBlock { id: impl_id.clone(), module: module.clone(), struct_id: struct_id.clone(), trait_id: trait_id.clone(), functions: vec![] });
        }
        ChangePayload::AddFunction { function_id, impl_id, signature } => {
            if ir.functions.iter().any(|f| f.id == *function_id) {
                return Err(EvolutionError::DuplicateArtifact(function_id.clone()));
            }
            let block_index = ir.impls.iter().position(|i| i.id == *impl_id).ok_or_else(|| EvolutionError::UnknownImpl(impl_id.clone()))?;
            let trait_id = ir.impls[block_index].trait_id.clone();
            let module = ir.impls[block_index].module.clone();
            ensure_trait_function_exists(ir, &trait_id, &signature.trait_function)?;
            ir.functions.push(crate::ir::Function {
                receiver: crate::ir::Receiver::None,
                id: function_id.clone(),
                name: signature.name.clone(),
                module,
                impl_id: impl_id.clone(),
                trait_function: signature.trait_function.clone(),
                visibility: signature.visibility,
                doc: signature.doc.clone(),
                lifetime_params: signature.lifetime_params.clone(),
                is_async: signature.is_async,
                is_unsafe: signature.is_unsafe,
                generics: signature.generics.clone(),
                where_clauses: signature.where_clauses.clone(),
                inputs: signature.inputs.clone(),
                outputs: signature.outputs.clone(),
                deltas: vec![],
                contract: crate::ir::FunctionContract { total: true, deterministic: true, explicit_inputs: true, explicit_outputs: true, effects_are_deltas: true },
                metadata: crate::ir::FunctionMetadata::default(),
            });
            ir.impls[block_index].functions.push(crate::ir::ImplFunctionBinding { trait_fn: signature.trait_function.clone(), function: function_id.clone() });
        }
        ChangePayload::AddModuleEdge { from, to, rationale } => {
            ensure_module_exists(ir, from)?;
            ensure_module_exists(ir, to)?;
            if ir.module_edges.iter().any(|e| &e.source == from && &e.target == to) {
                return Err(EvolutionError::DuplicateArtifact(format!("{from}->{to}")));
            }
            ir.module_edges.push(ModuleEdge { source: from.clone(), target: to.clone(), rationale: rationale.clone(), imported_types: Vec::new() });
        }
        ChangePayload::AddCallEdge { caller, callee } => {
            ensure_function_exists(ir, caller)?;
            ensure_function_exists(ir, callee)?;
            if ir.call_edges.iter().any(|e| e.caller == *caller && e.callee == *callee) {
                return Err(EvolutionError::DuplicateArtifact(format!("{caller}->{callee}")));
            }
            ir.call_edges.push(crate::ir::CallEdge { id: format!("call:{}:{}", caller, callee), caller: caller.clone(), callee: callee.clone(), rationale: "delta-applied".to_string() });
        }
        ChangePayload::AttachExecutionEvent { execution_id, event } => {
            let record = ir.executions.iter_mut().find(|e| e.id == *execution_id).ok_or_else(|| EvolutionError::UnknownExecution(execution_id.clone()))?;
            record.events.push(event.clone());
        }
        ChangePayload::UpdateFunctionAst { function_id, ast } => {
            let function = ir.functions.iter_mut().find(|f| f.id == *function_id).ok_or_else(|| EvolutionError::UnknownFunction(function_id.clone()))?;
            function.metadata.ast = Some(ast.clone());
        }
        ChangePayload::UpdateFunctionInputs { function_id, inputs } => {
            let function = ir.functions.iter_mut().find(|f| f.id == *function_id).ok_or_else(|| EvolutionError::UnknownFunction(function_id.clone()))?;
            function.inputs = inputs.clone();
        }
        ChangePayload::UpdateFunctionOutputs { function_id, outputs } => {
            let function = ir.functions.iter_mut().find(|f| f.id == *function_id).ok_or_else(|| EvolutionError::UnknownFunction(function_id.clone()))?;
            function.outputs = outputs.clone();
        }
        ChangePayload::AddEnum { module, enum_id, name, visibility } => {
            if ir.enums.iter().any(|e| e.id == *enum_id) {
                return Err(EvolutionError::DuplicateArtifact(enum_id.clone()));
            }
            ensure_module_exists(ir, module)?;
            ir.enums.push(crate::ir::EnumNode { id: enum_id.clone(), name: name.clone(), module: module.clone(), visibility: *visibility, variants: vec![], history: vec![] });
        }
        ChangePayload::AddEnumVariant { enum_id, variant } => {
            let target = ir.enums.iter_mut().find(|e| e.id == *enum_id).ok_or_else(|| EvolutionError::UnknownEnum(enum_id.clone()))?;
            if target.variants.iter().any(|v| v.name == variant.name) {
                return Err(EvolutionError::DuplicateArtifact(variant.name.as_str().to_string()));
            }
            target.variants.push(variant.clone());
        }
        ChangePayload::RecordReward { record } => {
            if ir.reward_deltas.iter().any(|r| r.id == record.id) {
                return Err(EvolutionError::DuplicateArtifact(record.id.clone()));
            }
            ir.reward_deltas.push(record.clone());
        }
        _ => {}
    }
    Ok(())
}

use super::super::EvolutionError;
use crate::ir::SystemState;
pub fn ensure_module_exists(ir: &SystemState, module: &str) -> Result<(), EvolutionError> {
    if ir.modules.iter().any(|m| m.id == module) {
        Ok(())
    } else {
        Err(EvolutionError::UnknownModule(module.to_string()))
    }
}
pub fn ensure_struct_exists(ir: &SystemState, struct_id: &str) -> Result<(), EvolutionError> {
    if ir.structs.iter().any(|s| s.id == struct_id) {
        Ok(())
    } else {
        Err(EvolutionError::UnknownStruct(struct_id.to_string()))
    }
}
pub fn ensure_field_exists(ir: &SystemState, struct_id: &str, field_name: &str) -> Result<(), EvolutionError> {
    let structure = ir.structs.iter().find(|s| s.id == struct_id).ok_or_else(|| EvolutionError::UnknownStruct(struct_id.to_string()))?;
    if structure.fields.iter().any(|f| f.name.as_str() == field_name) {
        Ok(())
    } else {
        Err(EvolutionError::UnknownField { struct_id: struct_id.to_string(), field: field_name.to_string() })
    }
}
pub fn ensure_trait_exists(ir: &SystemState, trait_id: &str) -> Result<(), EvolutionError> {
    if ir.traits.iter().any(|t| t.id == trait_id) {
        Ok(())
    } else {
        Err(EvolutionError::UnknownTrait(trait_id.to_string()))
    }
}
pub fn ensure_trait_function_exists(ir: &SystemState, trait_id: &str, trait_fn: &str) -> Result<(), EvolutionError> {
    let tr = ir.traits.iter().find(|t| t.id == trait_id).ok_or_else(|| EvolutionError::UnknownTrait(trait_id.to_string()))?;
    if tr.functions.iter().any(|f| f.id == trait_fn) {
        Ok(())
    } else {
        Err(EvolutionError::UnknownTraitFunction(trait_fn.to_string()))
    }
}
pub fn ensure_function_exists(ir: &SystemState, function_id: &str) -> Result<(), EvolutionError> {
    if ir.functions.iter().any(|f| f.id == function_id) {
        Ok(())
    } else {
        Err(EvolutionError::UnknownFunction(function_id.to_string()))
    }
}

use super::super::EvolutionError;
use crate::ir::SystemState;
pub fn rename_module(ir: &mut SystemState, old_id: &str, new_id: &str) -> Result<(), EvolutionError> {
    let module = ir.modules.iter_mut().find(|m| m.id == *old_id).ok_or_else(|| EvolutionError::UnknownModule(old_id.to_string()))?;
    module.id = new_id.to_owned();
    for structure in &mut ir.structs {
        if structure.module == *old_id {
            structure.module = new_id.to_owned();
        }
    }
    for tr in &mut ir.traits {
        if tr.module == *old_id {
            tr.module = new_id.to_owned();
        }
    }
    for block in &mut ir.impls {
        if block.module == *old_id {
            block.module = new_id.to_owned();
        }
    }
    for function in &mut ir.functions {
        if function.module == *old_id {
            function.module = new_id.to_owned();
        }
    }
    for edge in &mut ir.module_edges {
        if edge.source == *old_id {
            edge.source = new_id.to_owned();
        }
        if edge.target == *old_id {
            edge.target = new_id.to_owned();
        }
    }
    Ok(())
}
pub fn rename_struct(ir: &mut SystemState, old_id: &str, new_id: &str) -> Result<(), EvolutionError> {
    let structure = ir.structs.iter_mut().find(|s| s.id == *old_id).ok_or_else(|| EvolutionError::UnknownStruct(old_id.to_string()))?;
    structure.id = new_id.to_owned();
    for block in &mut ir.impls {
        if block.struct_id == *old_id {
            block.struct_id = new_id.to_owned();
        }
    }
    for function in &mut ir.functions {
        if function.module == *old_id {
            function.module = new_id.to_owned();
        }
    }
    Ok(())
}
pub fn rename_function(ir: &mut SystemState, old_id: &str, new_id: &str) -> Result<(), EvolutionError> {
    let function = ir.functions.iter_mut().find(|f| f.id == *old_id).ok_or_else(|| EvolutionError::UnknownFunction(old_id.to_string()))?;
    function.id = new_id.to_owned();
    for block in &mut ir.impls {
        for binding in &mut block.functions {
            if binding.function == *old_id {
                binding.function = new_id.to_owned();
            }
        }
    }
    for edge in &mut ir.call_edges {
        if edge.caller == *old_id {
            edge.caller = new_id.to_owned();
        }
        if edge.callee == *old_id {
            edge.callee = new_id.to_owned();
        }
    }
    Ok(())
}

//! Delta executor — applies CodeDeltas to disk then gates on `cargo check`.
//!
//! Flow:
//!   1. git stash          — clean rollback point
//!   2. apply each delta   — ApplyPatch via apply_patch(1), Bash via sh
//!   3. cargo check        — compile gate
//!   4. success → git stash drop   (keep changes)
//!      failure → git stash pop    (restore tree), return Err
use crate::ir::CodeDelta;
use std::io::Write;
use std::path::Path;
use std::process::{Command, Stdio};

#[derive(Debug)]
pub enum ExecutorError {
    /// git stash failed before we touched anything.
    StashFailed(String),
    /// apply_patch returned non-zero.
    PatchFailed { index: usize, stderr: String },
    /// A Bash delta returned non-zero.
    BashFailed { index: usize, command: String, stderr: String },
    /// cargo check failed after patches were applied — tree has been restored.
    CheckFailed(String),
    /// git stash pop failed — tree may be dirty.
    RollbackFailed(String),
    /// git stash drop failed (non-fatal, logged by caller).
    StashDropFailed(String),
}

impl std::fmt::Display for ExecutorError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ExecutorError::StashFailed(e) => write!(f, "git stash failed: {e}"),
            ExecutorError::PatchFailed { index, stderr } => {
                write!(f, "apply_patch[{index}] failed: {stderr}")
            }
            ExecutorError::BashFailed { index, command, stderr } => {
                write!(f, "bash delta[{index}] `{command}` failed: {stderr}")
            }
            ExecutorError::CheckFailed(e) => write!(f, "cargo check failed: {e}"),
            ExecutorError::RollbackFailed(e) => write!(f, "git stash pop failed: {e}"),
            ExecutorError::StashDropFailed(e) => write!(f, "git stash drop failed: {e}"),
        }
    }
}

impl std::error::Error for ExecutorError {}

/// Apply `deltas` to disk inside `workspace`, gate on `cargo check`.
///
/// On any failure the working tree is restored via `git stash pop`.
/// On success the stash is dropped and the changes remain on disk.
pub fn execute_deltas(deltas: &[CodeDelta], workspace: &Path) -> Result<(), ExecutorError> {
    if deltas.is_empty() {
        return Ok(());
    }

    // 1. Stash the current working tree so we have a clean rollback point.
    git_stash(workspace)?;

    // 2. Apply each delta in order.
    for (i, delta) in deltas.iter().enumerate() {
        let result = match delta {
            CodeDelta::ApplyPatch { patch } => run_apply_patch(patch, workspace, i),
            CodeDelta::Bash { command } | CodeDelta::BashReadOnly { command } => run_bash(command, workspace, i),
        };
        if let Err(e) = result {
            // Something failed mid-way — restore the tree before returning.
            rollback(workspace)?;
            return Err(e);
        }
    }

    // 3. Compile gate.
    let check = Command::new("cargo").args(["check"]).current_dir(workspace).output().map_err(|e| ExecutorError::CheckFailed(e.to_string()))?;

    if !check.status.success() {
        let stderr = String::from_utf8_lossy(&check.stderr).into_owned();
        rollback(workspace)?;
        return Err(ExecutorError::CheckFailed(stderr));
    }

    // 4. Success — discard the stash, keep changes on disk.
    let drop = Command::new("git").args(["stash", "drop"]).current_dir(workspace).output().map_err(|e| ExecutorError::StashDropFailed(e.to_string()))?;

    if !drop.status.success() {
        let stderr = String::from_utf8_lossy(&drop.stderr).into_owned();
        return Err(ExecutorError::StashDropFailed(stderr));
    }

    Ok(())
}

// ── internals ────────────────────────────────────────────────────────────────

fn git_stash(workspace: &Path) -> Result<(), ExecutorError> {
    let out = Command::new("git").args(["stash"]).current_dir(workspace).output().map_err(|e| ExecutorError::StashFailed(e.to_string()))?;

    if !out.status.success() {
        let stderr = String::from_utf8_lossy(&out.stderr).into_owned();
        return Err(ExecutorError::StashFailed(stderr));
    }
    Ok(())
}

fn rollback(workspace: &Path) -> Result<(), ExecutorError> {
    let out = Command::new("git").args(["stash", "pop"]).current_dir(workspace).output().map_err(|e| ExecutorError::RollbackFailed(e.to_string()))?;

    if !out.status.success() {
        let stderr = String::from_utf8_lossy(&out.stderr).into_owned();
        return Err(ExecutorError::RollbackFailed(stderr));
    }
    Ok(())
}

fn run_apply_patch(patch: &str, workspace: &Path, index: usize) -> Result<(), ExecutorError> {
    let mut child = Command::new("apply_patch").stdin(Stdio::piped()).stderr(Stdio::piped()).current_dir(workspace).spawn().map_err(|e| ExecutorError::PatchFailed { index, stderr: e.to_string() })?;

    if let Some(stdin) = child.stdin.take() {
        let mut stdin = stdin;
        stdin.write_all(patch.as_bytes()).map_err(|e| ExecutorError::PatchFailed { index, stderr: e.to_string() })?;
    }

    let out = child.wait_with_output().map_err(|e| ExecutorError::PatchFailed { index, stderr: e.to_string() })?;

    if !out.status.success() {
        let stderr = String::from_utf8_lossy(&out.stderr).into_owned();
        return Err(ExecutorError::PatchFailed { index, stderr });
    }
    Ok(())
}

fn run_bash(command: &str, workspace: &Path, index: usize) -> Result<(), ExecutorError> {
    let out = Command::new("sh").args(["-c", command]).current_dir(workspace).output().map_err(|e| ExecutorError::BashFailed { index, command: command.to_string(), stderr: e.to_string() })?;

    if !out.status.success() {
        let stderr = String::from_utf8_lossy(&out.stderr).into_owned();
        return Err(ExecutorError::BashFailed { index, command: command.to_string(), stderr });
    }
    Ok(())
}

