pub struct CapabilityPipeline {
    bridge: WsBridge,
    config: CapabilityConfig,
    tabs: engine::TabsHandle,
    role_rr: tokio::sync::Mutex<HashMap<String, usize>>,
}

impl CapabilityPipeline {
    pub fn new(bridge: WsBridge) -> Self {
        let config = CapabilityConfig::load().expect("failed to load capability config");
        Self { bridge, config, tabs: engine::new_tabs(), role_rr: tokio::sync::Mutex::new(HashMap::new()) }
    }

    fn ensure_log_dir() {
        let _ = std::fs::create_dir_all(LOG_ROOT);
        let _ = std::fs::create_dir_all("/workspace/ai_sandbox/canon/agent_logs");
        let _ = std::fs::create_dir_all("/workspace/ai_sandbox/canon/agent_logs/templates");
        Self::ensure_agent_log_files();
    }

    fn ensure_agent_log_files() {
        Self::ensure_file("/workspace/ai_sandbox/canon/agent_logs/policy_dataset.jsonl", "");
        Self::ensure_file("/workspace/ai_sandbox/canon/agent_logs/goal_embeddings.json", "{}");
        Self::ensure_file("/workspace/ai_sandbox/canon/agent_logs/metrics.json", "{}");
        Self::ensure_file("/workspace/ai_sandbox/canon/agent_logs/capability_costs.json", "{}");
        let weights_path = Path::new("/workspace/ai_sandbox/canon/agent_logs/policy_weights.json");
        if !weights_path.exists() {
            let model = PolicyModel::load_default();
            let _ = model.save(weights_path);
        }
    }

    fn ensure_file(path: &str, contents: &str) {
        let p = Path::new(path);
        if !p.exists() {
            if let Some(parent) = p.parent() {
                let _ = std::fs::create_dir_all(parent);
            }
            let _ = std::fs::write(p, contents);
        }
    }

    fn log_path(name: &str) -> PathBuf {
        Path::new(LOG_ROOT).join(name)
    }

    pub async fn run_capability_loop(&self, ctx: &PipelineContext) -> Result<f64> {
        Self::ensure_log_dir();
        if self.config.llm_endpoints.is_empty() {
            anyhow::bail!("capability config has no llm endpoints");
        }
        engine::init_io_workers(&self.bridge, &self.config, &self.tabs).await;

        let goal = GoalSpec::from_file(&self.config.goal_file)?;
        if let Ok(pretty) = serde_json::to_string_pretty(&goal) {
            let _ = std::fs::write(Self::log_path("goal_spec.json"), pretty);
        }

        let endpoint = self.config.llm_endpoints.iter().find(|e| e.role.as_deref() != Some("planner")).unwrap_or(&self.config.llm_endpoints[0]);
        let retry_count = self.config.llm_retry_count;
        let retry_delay = self.config.llm_retry_delay_secs;
        let max_output_lines = self.config.max_output_lines;
        let workspace_listing = list_workspace_entries(&ctx.cwd[0], 50);
        let policy = config::CapabilityPolicy::load(&ctx.cwd[0])?;
        let policy = config::CapabilityPolicy { max_node_retries: self.config.max_node_retries, ..policy };

        let mut store = TemplateStore::new(Path::new(TEMPLATE_ROOT).to_path_buf(), self.config.embedding_dim);
        let template_name = goal.raw.clone();

        let mut planner_generate = || async {
            let request = decompose::build_goal_request(&goal.raw, &ctx.cwd[0], &workspace_listing, Path::new(LOG_ROOT));
            let mut payload = engine::call_llm_json_with_retry_allow_mismatch(
                &self.bridge,
                &endpoint.id,
                &endpoint.url,
                endpoint.stateful,
                &request.prompt,
                "",
                request.phase,
                None,
                &self.tabs,
                endpoint.max_tabs,
                self.config.tab_cooldown_ms,
                self.config.llm_retry_count,
                self.config.llm_retry_delay_secs,
            )
            .await?;
            let mut extra_retries = 2u32;
            let decomp = loop {
                match decompose::evaluate_payload(payload.clone(), &request) {
                    Ok(output) => {
                        decompose::write_payload_log(&request.log_path, &payload);
                        break output;
                    }
                    Err(decompose::DecomposeRetry::Retry { prompt }) => {
                        if extra_retries == 0 {
                            return Err(anyhow::anyhow!("decompose_goal retries exhausted"));
                        }
                        extra_retries = extra_retries.saturating_sub(1);
                        payload = engine::call_llm_json_with_retry_allow_mismatch(
                            &self.bridge,
                            &endpoint.id,
                            &endpoint.url,
                            endpoint.stateful,
                            &prompt,
                            "",
                            request.phase,
                            None,
                            &self.tabs,
                            endpoint.max_tabs,
                            self.config.tab_cooldown_ms,
                            1,
                            self.config.llm_retry_delay_secs,
                        )
                        .await?;
                    }
                    Err(decompose::DecomposeRetry::EnsureRender { prompt, original }) => {
                        if extra_retries == 0 {
                            return Err(anyhow::anyhow!("decompose_goal retries exhausted"));
                        }
                        extra_retries = extra_retries.saturating_sub(1);
                        let retry_payload = engine::call_llm_json_with_retry_allow_mismatch(
                            &self.bridge,
                            &endpoint.id,
                            &endpoint.url,
                            endpoint.stateful,
                            &prompt,
                            "",
                            request.phase,
                            None,
                            &self.tabs,
                            endpoint.max_tabs,
                            self.config.tab_cooldown_ms,
                            1,
                            self.config.llm_retry_delay_secs,
                        )
                        .await?;
                        let retry_output = decompose::parse_payload(retry_payload.clone())?;
                        let merged = decompose::merge_outputs(original, retry_output);
                        let has_render = merged.tasks.iter().any(|t| t.node_type == decompose::NodeType::Render);
                        if !has_render {
                            return Err(anyhow::anyhow!("decompose_goal retry still missing render node"));
                        }
                        decompose::write_payload_log(&request.log_path, &retry_payload);
                        break merged;
                    }
                }
            };
            eprintln!("[capability] decompose_goal tasks={}", decomp.tasks.len());

            let mut nodes: Vec<dag::TaskNode> = decomp
                .tasks
                .into_iter()
                .map(|t| dag::TaskNode {
                    id: t.id,
                    description: t.description,
                    status: dag::Status::Pending,
                    deps: t.deps,
                    required_capabilities: t.required_capabilities,
                    node_type: t.node_type,
                    priority: t.priority,
                    budget: t.budget,
                    reasoning_trace: t.reasoning_trace,
                    result: None,
                    error: None,
                    readonly_fail_count: 0,
                    repair_attempts: 0,
                    completed_iter: None,
                })
                .collect();
            ensure_unique_node_ids(&mut nodes);
            ensure_unique_node_ids(&mut nodes);
            Ok::<dag::TaskGraph, anyhow::Error>(dag::TaskGraph { nodes, id_index: HashMap::new() })
        };

        let mut cache_hit = false;
        let mut graph = if self.config.enable_resume {
            let snap = state_snapshot::load(Path::new(&self.config.snapshot_file));
            if let Some(snapshot) = snap {
                telemetry::set_resume_iteration(snapshot.iteration);
                let mut g = snapshot.graph;
                g.reset_for_execution();
                dag::resolve_ready(&mut g);
                g
            } else {
                planner_generate().await?
            }
        } else if store.exists(&template_name) {
            match store.load(&template_name) {
                Ok(g) if g.validate().is_ok() => {
                    eprintln!("[templates] cache hit");
                    cache_hit = true;
                    g
                }
                _ => {
                    eprintln!("[templates] invalid template, evicting");
                    store.evict(&template_name);
                    let g = planner_generate().await?;
                    let _ = store.save(&template_name, &g);
                    g
                }
            }
        } else {
            eprintln!("[templates] cache miss — invoking planner");
            let g = planner_generate().await?;
            let _ = store.save(&template_name, &g);
            g
        };

        emit_planned_graph(&graph, Path::new(LOG_ROOT), 0);
        run_graph_algorithms(&graph, Path::new(LOG_ROOT), 0);

        if cache_hit && !self.config.planner_refine_on_cache {
            let mut exec_metrics = Default::default();
            let template_hash = store.hash_for(&template_name);
            let mut failure_store = failure_store::FailureStore::load(&template_hash);
            let mut cost_table = capability_cost::CapabilityCostTable::load();
            let (iterations_used, exec_failures) = scheduler::execute_graph_loop(
                &mut graph,
                &self.bridge,
                &self.config,
                &self.role_rr,
                &self.tabs,
                &ctx.cwd,
                &workspace_listing,
                endpoint,
                "exec",
                &policy,
                self.config.context_radius,
                self.config.max_concurrency,
                self.config.max_iterations,
                self.config.tab_cooldown_ms,
                retry_count,
                retry_delay,
                max_output_lines,
                0.0,
                &mut cost_table,
                &mut exec_metrics,
            )
            .await?;
            for failure in exec_failures {
                failure_store.record_graph(failure.kind, &graph, failure.iter);
                store.record_failure(&template_hash);
            }
            let features = graph_algo::graph_features(&graph).with_failure_stats(&failure_store.stats());
            let policy_outcome = policy_engine::evaluate(&features, self.config.max_nodes, self.config.max_nodes.saturating_mul(4));
            let reward = telemetry::compute_reward(&graph, iterations_used, self.config.max_iterations);
            let entry = PolicyDatasetEntry {
                features: serde_json::json!({
                    "nodes": features.nodes,
                    "edges": features.edges,
                    "depth": features.depth,
                    "scc_count": features.scc_count,
                    "failure_rate": features.failure_rate,
                    "reward_trend": features.reward_trend,
                    "avg_out_degree": features.avg_out_degree,
                    "avg_in_degree": features.avg_in_degree,
                    "branching_factor": features.branching_factor,
                    "leaf_count": features.leaf_count,
                    "root_count": features.root_count,
                    "verify_to_mutate_ratio": features.verify_to_mutate_ratio,
                    "observe_to_mutate_ratio": features.observe_to_mutate_ratio,
                    "node_type_entropy": features.node_type_entropy,
                    "avg_node_priority": features.avg_node_priority,
                    "avg_node_budget": features.avg_node_budget,
                    "blocked_fraction": features.blocked_fraction,
                    "ready_fraction": features.ready_fraction,
                    "failed_fraction": features.failed_fraction,
                    "completion_velocity": features.completion_velocity,
                    "retry_rate": features.retry_rate,
                    "failure_pattern_rate": features.failure_pattern_rate,
                    "cycle_frequency": features.cycle_frequency,
                    "deadlock_rate": features.deadlock_rate,
                    "failures": failure_store.failure_count(),
                }),
                action: serde_json::json!({
                    "add_nodes": 0,
                    "add_edges": 0,
                    "rewrites": 0
                }),
                policy_decision: serde_json::json!({
                    "run_planner": policy_outcome.decision.run_planner,
                    "expansion_scale": policy_outcome.decision.expansion_scale,
                    "execution_preference": policy_outcome.decision.execution_preference
                }),
                reward,
            };
            policy_train::append_policy_dataset(&entry);
            policy_train::update_online(&entry, self.config.max_nodes, self.config.max_nodes.saturating_mul(4));
            store.record_reward(&template_name, reward);
            let runtime = telemetry::RuntimeMetrics {
                queue_depth: telemetry::pending_requests(),
                retry_rate: 0.0,
                progress_fraction: telemetry::progress_fraction(&graph),
                iteration_time_ms: 0,
                branching_factor: features.branching_factor,
                blocked_fraction: features.blocked_fraction,
                completion_velocity: features.completion_velocity,
                policy_prediction: 0.0,
                policy_error: 0.0,
                policy_weight_norm: 0.0,
                dataset_size: 0,
                deadlock_rate: features.deadlock_rate,
                policy_run_planner: true,
                policy_expansion_scale: 1.0,
                policy_execution_preference: 0.0,
                template_reuse: false,
                template_score: 0.0,
                template_selected: None,
                repair_attempts: 0,
                repair_success_rate: 0.0,
                repair_type: None,
                constraint_rejections: 0,
                constraint_hit_rate: 0.0,
                constraint_types: None,
                avg_capability_latency: 0.0,
                avg_capability_failure: 0.0,
                avg_node_utility: 0.0,
                template_mutations: 0,
                mutation_success_rate: 0.0,
                mutation_reward_delta: 0.0,
                snapshot_written: false,
                snapshot_loaded: false,
                resume_iteration: 0,
                goal_similarity_score: 0.0,
                template_reuse_by_embedding: false,
                embedding_cache_hits: 0,
            };
            let snapshot = telemetry::TelemetrySnapshot {
                planner: Default::default(),
                exec: exec_metrics.clone(),
                runtime,
                reward,
                template_hash: Some(store.hash_for(&template_name)),
                goal: Some(template_name.clone()),
            };
            telemetry::record_snapshot(&Path::new(LOG_ROOT).join("metrics.json"), &snapshot);
            telemetry::record_snapshot(&Path::new("/workspace/ai_sandbox/canon/agent_logs/metrics.json"), &snapshot);
            let _ = std::fs::create_dir_all(Path::new(TEMPLATE_ROOT));
            telemetry::record_snapshot(&Path::new(TEMPLATE_ROOT).join(format!("metrics_{}.json", template_hash)), &snapshot);
            Ok(reward)
        } else {
            let planner_endpoint = self.config.planner_endpoint()?;
            let mut planner_session = planner_session::PlannerSession::new(planner_endpoint, goal.raw.clone());
            let recent = store.recent_rewards(&template_name, 4);
            let plateaued = store.is_plateaued(&template_name, self.config.planner_plateau_window, self.config.planner_plateau_threshold);
            let similar = store.find_similar(&goal.raw, &graph, 1, self.config.goal_similarity_weight, self.config.structural_similarity_weight, self.config.embedding_dim);
            let bootstrap_seed = similar.templates.into_iter().next().map(|s| {
                let seed_graph = store.load(&s.entry.goal).ok();
                let node_summaries = seed_graph.as_ref().map(|g| g.nodes.iter().map(|n| format!("{}: {}", n.id, n.description)).collect::<Vec<_>>()).unwrap_or_default();
                planner_session::BootstrapSeed {
                    goal: s.entry.goal.clone(),
                    similarity_score: s.score,
                    reward: s.entry.reward,
                    node_summaries,
                    capability_set: s.entry.capability_set.clone(),
                    node_count: s.entry.node_count,
                    edge_count: s.entry.edge_count,
                }
            });
            let reward_ctx = planner_session::RewardContext {
                recent_rewards: recent,
                plateaued,
                best_reward: store.stored_reward(&template_name),
                stored_reward: store.stored_reward(&template_name),
                bootstrap_seed,
            };
            planner_session.set_reward_context(reward_ctx);
            scheduler::run_planner_execution_loop(
                &mut planner_session,
                &mut graph,
                &self.bridge,
                &self.config,
                &self.role_rr,
                &self.tabs,
                &ctx.cwd,
                &workspace_listing,
                endpoint,
                "exec",
                &policy,
                self.config.context_radius,
                self.config.max_concurrency,
                self.config.max_iterations,
                self.config.tab_cooldown_ms,
                retry_count,
                retry_delay,
                max_output_lines,
                &mut store,
                &template_name,
            )
            .await
        }
    }
}

fn list_workspace_entries(root: &Path, limit: usize) -> String {
    let mut entries: Vec<String> = std::fs::read_dir(root).map(|rd| rd.filter_map(|e| e.ok()).map(|e| e.file_name().to_string_lossy().to_string()).collect::<Vec<_>>()).unwrap_or_default();
    entries.sort();
    entries.truncate(limit);
    entries.join(", ")
}

fn ensure_unique_node_ids(nodes: &mut Vec<dag::TaskNode>) {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for n in nodes.iter_mut() {
        let count = counts.entry(n.id.clone()).or_insert(0);
        if *count > 0 {
            let new_id = format!("{}__{}", n.id, *count);
            n.id = new_id;
        }
        *count += 1;
    }
}

#[async_trait::async_trait]
impl Pipeline for CapabilityPipeline {
    fn name(&self) -> &str {
        "capability"
    }

    async fn run_tick(&self, ctx: &PipelineContext, _ir: &mut SystemState, _layout: &mut FileTopology) -> Result<PipelineOutcome> {
        match self.run_capability_loop(ctx).await {
            Ok(reward) => Ok(PipelineOutcome { reward, summary: "capability completed".into(), advanced: true }),
            Err(e) => Ok(PipelineOutcome { reward: -1.0, summary: format!("capability error: {e}"), advanced: false }),
        }
    }
}

use super::Delta;
use serde::Serialize;
use std::path::{Path, PathBuf};

use super::executor_dispatch;

#[derive(Debug, Clone, Serialize)]
pub struct DeltaOutcome {
    pub delta: Delta,
    pub status: String,
    pub message: String,
}

#[derive(Debug, Clone)]
pub struct DeltaRepairLog {
    pub original: Delta,
    pub repaired: Delta,
    pub reason: String,
}

pub fn apply_read_only(deltas: &[Delta], roots: &[PathBuf], max_output_lines: usize) -> (String, Vec<DeltaOutcome>, Option<String>) {
    let mut output = String::new();
    let mut results = Vec::new();
    let mut error: Option<String> = None;
    let mut repairs = Vec::new();

    for delta in deltas {
        let delta = repair_delta_path(delta, roots, &mut repairs);
        match executor_dispatch::execute_read_only(&delta, roots, max_output_lines) {
            Ok((msg, out)) => {
                results.push(DeltaOutcome { delta: delta.clone(), status: "ok".into(), message: msg });
                output.push_str(out.trim_end_matches('\n'));
                output.push('\n');
            }
            Err(e) => {
                let msg = format!("ERROR: {e}");
                results.push(DeltaOutcome { delta: delta.clone(), status: "error".into(), message: msg.clone() });
                output.push_str(&msg);
                output.push('\n');
                let _ = error.get_or_insert(msg);
            }
        }
    }
    if !repairs.is_empty() {
        output.push_str("[delta_repair]\n");
        for r in repairs {
            output.push_str(&format!("{} => {} ({})\n", delta_label(&r.original), delta_label(&r.repaired), r.reason));
        }
    }

    (output, results, error)
}

pub fn summarize_deltas(deltas: &[Delta]) -> Vec<serde_json::Value> {
    deltas
        .iter()
        .map(|d| match d {
            Delta::ReadFile { path } => serde_json::json!({"type":"read_file","path":path}),
            Delta::ListDir { path } => serde_json::json!({"type":"list_dir","path":path}),
            Delta::ReadCommand { command, args } => serde_json::json!({"type":"read_command","command":command,"args":args}),
            Delta::WriteFile { path, .. } => serde_json::json!({"type":"write_file","path":path}),
            Delta::ReplaceText { path, .. } => serde_json::json!({"type":"replace_text","path":path}),
            Delta::DeleteFile { path } => serde_json::json!({"type":"delete_file","path":path}),
        })
        .collect()
}

pub fn apply_mutations(deltas: &[Delta], roots: &[PathBuf], allowed_write_roots: &[PathBuf], max_output_lines: usize) -> (String, Vec<DeltaOutcome>, Option<String>) {
    let mut output = String::new();
    let mut results = Vec::new();
    let mut error: Option<String> = None;
    let mut repairs = Vec::new();

    for delta in deltas {
        let delta = repair_delta_path(delta, roots, &mut repairs);
        match executor_dispatch::execute_mutation(&delta, roots, allowed_write_roots, max_output_lines) {
            Ok(msg) => {
                results.push(DeltaOutcome { delta: delta.clone(), status: "ok".into(), message: msg.clone() });
                output.push_str(&msg);
                output.push('\n');
            }
            Err(e) => {
                let msg = format!("ERROR: {e}");
                results.push(DeltaOutcome { delta: delta.clone(), status: "error".into(), message: msg.clone() });
                output.push_str(&msg);
                output.push('\n');
                let _ = error.get_or_insert(msg);
            }
        }
    }
    if !repairs.is_empty() {
        output.push_str("[delta_repair]\n");
        for r in repairs {
            output.push_str(&format!("{} => {} ({})\n", delta_label(&r.original), delta_label(&r.repaired), r.reason));
        }
    }

    (output, results, error)
}

fn repair_delta_path(delta: &Delta, roots: &[PathBuf], repairs: &mut Vec<DeltaRepairLog>) -> Delta {
    let root = roots.get(0).cloned().unwrap_or_else(|| PathBuf::from("/"));
    match delta {
        Delta::ReadFile { path } | Delta::ListDir { path } => {
            let p = Path::new(path);
            if p.is_absolute() && !p.exists() {
                let repaired = match delta {
                    Delta::ReadFile { .. } => Delta::ReadFile { path: root.display().to_string() },
                    Delta::ListDir { .. } => Delta::ListDir { path: root.display().to_string() },
                    _ => delta.clone(),
                };
                repairs.push(DeltaRepairLog { original: delta.clone(), repaired: repaired.clone(), reason: "path does not exist; redirected to workspace root".to_string() });
                return repaired;
            }
            delta.clone()
        }
        _ => delta.clone(),
    }
}

fn delta_label(delta: &Delta) -> String {
    match delta {
        Delta::ReadFile { path } => format!("read_file {}", path),
        Delta::ListDir { path } => format!("list_dir {}", path),
        Delta::ReadCommand { command, args } => format!("read_command {} {}", command, args.join(" ")),
        Delta::WriteFile { path, .. } => format!("write_file {}", path),
        Delta::ReplaceText { path, .. } => format!("replace_text {}", path),
        Delta::DeleteFile { path } => format!("delete_file {}", path),
    }
}

pub(crate) fn resolve_path(path: &str, roots: &[PathBuf], allow_nonexistent: bool) -> Result<PathBuf, String> {
    let p = Path::new(path);
    if has_parent_dir_component(&[path.to_string()]) {
        return Err(format!("path contains '..': {}", path));
    }

    let resolved = anchor(p, &roots[0]);

    if !is_within_roots(&resolved, roots) {
        return Err(format!("path escapes allowed roots: {}", resolved.display()));
    }

    if !allow_nonexistent && !resolved.exists() {
        return Err(format!("path does not exist: {}", resolved.display()));
    }

    Ok(resolved)
}

fn anchor(p: &Path, root: &Path) -> PathBuf {
    if p.is_absolute() {
        p.to_path_buf()
    } else {
        root.join(p)
    }
}

pub(crate) fn is_within_roots(path: &Path, roots: &[PathBuf]) -> bool {
    roots.iter().any(|root| path.starts_with(root))
}

pub(crate) fn has_parent_dir_component(args: &[String]) -> bool {
    args.iter().any(|a| a.split('/').any(|c| c == ".."))
}

pub(crate) fn truncate_lines(text: &str, max_lines: usize) -> String {
    let mut iter = text.lines();
    let kept: Vec<&str> = iter.by_ref().take(max_lines).collect();
    let remaining = iter.count();
    let mut out = kept.join("\n");
    if remaining > 0 {
        out.push_str(&format!("\n... [{} lines truncated] ...", remaining));
    }
    out
}

use std::collections::HashMap;
use std::path::Path;

use serde::{Deserialize, Serialize};

use super::capability::Capability;
use super::dag::TaskNode;

const COST_PATH: &str = "/workspace/ai_sandbox/canon/agent_logs/capability_costs.json";

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct CapabilityCost {
    pub latency_avg: f64,
    pub failure_rate: f64,
    pub samples: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct CapabilityCostTable {
    pub costs: HashMap<Capability, CapabilityCost>,
}

impl CapabilityCostTable {
    pub fn load() -> Self {
        std::fs::read_to_string(COST_PATH).ok().and_then(|s| serde_json::from_str::<CapabilityCostTable>(&s).ok()).unwrap_or_default()
    }

    pub fn save(&self) {
        if let Ok(pretty) = serde_json::to_string_pretty(self) {
            let _ = std::fs::create_dir_all(Path::new(COST_PATH).parent().unwrap_or(Path::new(".")));
            let _ = std::fs::write(COST_PATH, pretty);
        }
    }

    pub fn update(&mut self, cap: Capability, latency_ms: f64, success: bool, decay: f64) {
        let decay = decay.clamp(0.0, 1.0);
        let entry = self.costs.entry(cap).or_default();
        let failure = if success { 0.0 } else { 1.0 };
        if entry.samples == 0 {
            entry.latency_avg = latency_ms;
            entry.failure_rate = failure;
        } else {
            entry.latency_avg = (1.0 - decay) * entry.latency_avg + decay * latency_ms;
            entry.failure_rate = (1.0 - decay) * entry.failure_rate + decay * failure;
        }
        entry.samples = entry.samples.saturating_add(1);
    }

    pub fn node_cost(&self, caps: &[Capability], latency_weight: f64, failure_weight: f64) -> f64 {
        caps.iter().map(|c| self.costs.get(c)).flatten().map(|c| latency_weight * c.latency_avg + failure_weight * c.failure_rate).sum()
    }

    pub fn avg_latency(&self) -> f64 {
        let mut total = 0.0;
        let mut count = 0u64;
        for c in self.costs.values() {
            if c.samples > 0 {
                total += c.latency_avg;
                count += 1;
            }
        }
        if count == 0 {
            0.0
        } else {
            total / count as f64
        }
    }

    pub fn avg_failure(&self) -> f64 {
        let mut total = 0.0;
        let mut count = 0u64;
        for c in self.costs.values() {
            if c.samples > 0 {
                total += c.failure_rate;
                count += 1;
            }
        }
        if count == 0 {
            0.0
        } else {
            total / count as f64
        }
    }

    pub fn summary(&self, max_entries: usize, latency_weight: f64, failure_weight: f64) -> String {
        let mut entries: Vec<(Capability, f64, f64, f64)> = self
            .costs
            .iter()
            .map(|(cap, cost)| {
                let score = latency_weight * cost.latency_avg + failure_weight * cost.failure_rate;
                (*cap, cost.latency_avg, cost.failure_rate, score)
            })
            .collect();
        entries.sort_by(|a, b| b.3.partial_cmp(&a.3).unwrap_or(std::cmp::Ordering::Equal));
        entries.truncate(max_entries);
        let mut lines = Vec::new();
        for (cap, lat, fail, score) in entries {
            lines.push(format!("{:?}: latency_ms={:.1} fail_rate={:.2} cost={:.2}", cap, lat, fail, score));
        }
        lines.join("\n")
    }
}

pub fn apply_node_cost_update(table: &mut CapabilityCostTable, node: &TaskNode, latency_ms: f64, success: bool, decay: f64, latency_weight: f64, failure_weight: f64) -> f64 {
    for cap in &node.required_capabilities {
        table.update(*cap, latency_ms, success, decay);
    }
    table.node_cost(&node.required_capabilities, latency_weight, failure_weight)
}

