pub fn graph_features(graph: &dag::TaskGraph) -> FeatureVector {
    let signals = compute_graph_signals(graph);
    let nodes = graph.nodes.len();
    let edges = graph.nodes.iter().map(|n| n.deps.len()).sum();
    let depth = compute_max_depth(graph);
    let failed = graph.nodes.iter().filter(|n| n.status == dag::Status::Failed).count();
    let failure_rate = if nodes == 0 { 0.0 } else { failed as f64 / nodes as f64 };
    #[cfg(feature = "cuda")]
    let (
        root_count,
        leaf_count,
        avg_out_degree,
        avg_in_degree,
        branching_factor,
        verify_to_mutate_ratio,
        observe_to_mutate_ratio,
        node_type_entropy,
        avg_node_priority,
        avg_node_budget,
        blocked_fraction,
        ready_fraction,
        failed_fraction,
        completion_velocity,
        retry_rate,
    ) = {
        let mut adj: Vec<Vec<usize>> = vec![Vec::new(); nodes];
        let mut id_to_idx: HashMap<&str, usize> = HashMap::new();
        for (i, n) in graph.nodes.iter().enumerate() {
            id_to_idx.insert(n.id.as_str(), i);
        }
        for n in &graph.nodes {
            if let Some(&to) = id_to_idx.get(n.id.as_str()) {
                for dep in &n.deps {
                    if let Some(&from) = id_to_idx.get(dep.as_str()) {
                        adj[from].push(to);
                    }
                }
            }
        }
        let csr = Csr::from_adj(&adj);
        let (indegree, outdegree) = algorithms::graph::feature_gpu::indegree_outdegree(&csr);
        let status = graph.nodes.iter().map(|n| n.status as u8).collect::<Vec<_>>();
        let priority = graph.nodes.iter().map(|n| n.priority as u16).collect::<Vec<_>>();
        let budget = graph.nodes.iter().map(|n| n.budget.unwrap_or(0) as u32).collect::<Vec<_>>();
        let retry = graph.nodes.iter().map(|n| n.readonly_fail_count as u32).collect::<Vec<_>>();
        let mut has_verify = Vec::with_capacity(nodes);
        let mut has_mutate = Vec::with_capacity(nodes);
        let mut has_observe = Vec::with_capacity(nodes);
        let mut node_type = Vec::with_capacity(nodes);
        let mut max_completed_iter = 0u64;
        let mut completed = 0usize;
        for n in &graph.nodes {
            let mut v = 0u8;
            let mut m = 0u8;
            let mut o = 0u8;
            for cap in &n.required_capabilities {
                match cap.class() {
                    super::capability::CapabilityClass::Verify => v = 1,
                    super::capability::CapabilityClass::Mutate => m = 1,
                    super::capability::CapabilityClass::Observe => o = 1,
                }
            }
            has_verify.push(v);
            has_mutate.push(m);
            has_observe.push(o);
            node_type.push(if n.node_type == decompose::NodeType::Analysis { 0 } else { 1 });
            if n.status == dag::Status::Completed {
                completed += 1;
                if let Some(t) = n.completed_iter {
                    max_completed_iter = max_completed_iter.max(t);
                }
            }
        }
        let stats = algorithms::graph::feature_gpu::feature_stats_gpu(&status, &indegree, &outdegree, &priority, &budget, &retry, &has_verify, &has_mutate, &has_observe, &node_type);
        let avg_out_degree = if nodes == 0 { 0.0 } else { edges as f64 / nodes as f64 };
        let avg_in_degree = avg_out_degree;
        let branching_factor = if stats.non_leaf_count == 0 { 0.0 } else { stats.outdegree_sum as f64 / stats.non_leaf_count as f64 };
        let verify_to_mutate_ratio = if stats.mutate_count == 0 { 0.0 } else { stats.verify_count as f64 / stats.mutate_count as f64 };
        let observe_to_mutate_ratio = if stats.mutate_count == 0 { 0.0 } else { stats.observe_count as f64 / stats.mutate_count as f64 };
        let total = nodes.max(1) as f64;
        let p_a = stats.analysis_count as f64 / total;
        let p_r = stats.render_count as f64 / total;
        let h = |p: f64| if p <= 0.0 { 0.0 } else { -p * p.ln() };
        let node_type_entropy = h(p_a) + h(p_r);
        let avg_node_priority = if nodes == 0 { 0.0 } else { stats.priority_sum as f64 / nodes as f64 };
        let avg_node_budget = if nodes == 0 { 0.0 } else { stats.budget_sum as f64 / nodes as f64 };
        let blocked_fraction = if nodes == 0 { 0.0 } else { stats.blocked_count as f64 / nodes as f64 };
        let ready_fraction = if nodes == 0 { 0.0 } else { stats.ready_count as f64 / nodes as f64 };
        let failed_fraction = if nodes == 0 { 0.0 } else { stats.failed_count as f64 / nodes as f64 };
        let completion_velocity = if completed == 0 { 0.0 } else { completed as f64 / (max_completed_iter.max(1) as f64 + 1.0) };
        let retry_rate = if nodes == 0 { 0.0 } else { stats.retry_sum as f64 / nodes as f64 };
        (
            stats.root_count as usize,
            stats.leaf_count as usize,
            avg_out_degree,
            avg_in_degree,
            branching_factor,
            verify_to_mutate_ratio,
            observe_to_mutate_ratio,
            node_type_entropy,
            avg_node_priority,
            avg_node_budget,
            blocked_fraction,
            ready_fraction,
            failed_fraction,
            completion_velocity,
            retry_rate,
        )
    };
    #[cfg(not(feature = "cuda"))]
    let (
        root_count,
        leaf_count,
        avg_out_degree,
        avg_in_degree,
        branching_factor,
        verify_to_mutate_ratio,
        observe_to_mutate_ratio,
        node_type_entropy,
        avg_node_priority,
        avg_node_budget,
        blocked_fraction,
        ready_fraction,
        failed_fraction,
        completion_velocity,
        retry_rate,
    ) = {
        let mut indegree = vec![0usize; nodes];
        let mut outdegree = vec![0usize; nodes];
        let mut id_to_idx: HashMap<&str, usize> = HashMap::new();
        for (i, n) in graph.nodes.iter().enumerate() {
            id_to_idx.insert(n.id.as_str(), i);
            indegree[i] = n.deps.len();
        }
        for n in &graph.nodes {
            for dep in &n.deps {
                if let Some(&idx) = id_to_idx.get(dep.as_str()) {
                    outdegree[idx] += 1;
                }
            }
        }
        let root_count = graph.nodes.iter().filter(|n| n.deps.is_empty()).count();
        let leaf_count = outdegree.iter().filter(|&&d| d == 0).count();
        let avg_out_degree = if nodes == 0 { 0.0 } else { edges as f64 / nodes as f64 };
        let avg_in_degree = avg_out_degree;
        let branching_factor = {
            let non_leaf = outdegree.iter().filter(|&&d| d > 0).count();
            if non_leaf == 0 {
                0.0
            } else {
                outdegree.iter().sum::<usize>() as f64 / non_leaf as f64
            }
        };
        let mut verify_count = 0usize;
        let mut mutate_count = 0usize;
        let mut observe_count = 0usize;
        let mut analysis_count = 0usize;
        let mut render_count = 0usize;
        let mut priority_sum = 0f64;
        let mut budget_sum = 0f64;
        let mut blocked = 0usize;
        let mut ready = 0usize;
        let mut failed_count = 0usize;
        let mut completed = 0usize;
        let mut retry_total = 0f64;
        let mut max_completed_iter = 0u64;
        for n in &graph.nodes {
            if n.node_type == decompose::NodeType::Analysis {
                analysis_count += 1;
            } else {
                render_count += 1;
            }
            for cap in &n.required_capabilities {
                match cap.class() {
                    super::capability::CapabilityClass::Verify => verify_count += 1,
                    super::capability::CapabilityClass::Mutate => mutate_count += 1,
                    super::capability::CapabilityClass::Observe => observe_count += 1,
                }
            }
            priority_sum += n.priority as f64;
            if let Some(b) = n.budget {
                budget_sum += b as f64;
            }
            match n.status {
                dag::Status::Blocked => blocked += 1,
                dag::Status::Ready => ready += 1,
                dag::Status::Failed => failed_count += 1,
                dag::Status::Completed => {
                    completed += 1;
                    if let Some(t) = n.completed_iter {
                        max_completed_iter = max_completed_iter.max(t);
                    }
                }
                _ => {}
            }
            retry_total += n.readonly_fail_count as f64;
        }
        let verify_to_mutate_ratio = if mutate_count == 0 { 0.0 } else { verify_count as f64 / mutate_count as f64 };
        let observe_to_mutate_ratio = if mutate_count == 0 { 0.0 } else { observe_count as f64 / mutate_count as f64 };
        let node_type_entropy = {
            let total = nodes.max(1) as f64;
            let p_a = analysis_count as f64 / total;
            let p_r = render_count as f64 / total;
            let h = |p: f64| if p <= 0.0 { 0.0 } else { -p * p.ln() };
            h(p_a) + h(p_r)
        };
        let avg_node_priority = if nodes == 0 { 0.0 } else { priority_sum / nodes as f64 };
        let avg_node_budget = if nodes == 0 { 0.0 } else { budget_sum / nodes as f64 };
        let blocked_fraction = if nodes == 0 { 0.0 } else { blocked as f64 / nodes as f64 };
        let ready_fraction = if nodes == 0 { 0.0 } else { ready as f64 / nodes as f64 };
        let failed_fraction = if nodes == 0 { 0.0 } else { failed_count as f64 / nodes as f64 };
        let completion_velocity = if completed == 0 { 0.0 } else { completed as f64 / (max_completed_iter.max(1) as f64 + 1.0) };
        let retry_rate = if nodes == 0 { 0.0 } else { retry_total / nodes as f64 };
        (
            root_count,
            leaf_count,
            avg_out_degree,
            avg_in_degree,
            branching_factor,
            verify_to_mutate_ratio,
            observe_to_mutate_ratio,
            node_type_entropy,
            avg_node_priority,
            avg_node_budget,
            blocked_fraction,
            ready_fraction,
            failed_fraction,
            completion_velocity,
            retry_rate,
        )
    };
    FeatureVector {
        nodes,
        edges,
        depth,
        scc_count: signals.sccs.len(),
        failure_rate,
        reward_trend: 0.0,
        avg_out_degree,
        avg_in_degree,
        branching_factor,
        leaf_count,
        root_count,
        verify_to_mutate_ratio,
        observe_to_mutate_ratio,
        node_type_entropy,
        avg_node_priority,
        avg_node_budget,
        blocked_fraction,
        ready_fraction,
        failed_fraction,
        completion_velocity,
        retry_rate,
        failure_pattern_rate: 0.0,
        cycle_frequency: 0.0,
        deadlock_rate: 0.0,
    }
}

pub fn normalize_features(f: &FeatureVector, max_nodes: usize, max_edges: usize) -> Vec<f64> {
    let denom_nodes = max_nodes.max(1) as f64;
    let denom_edges = max_edges.max(1) as f64;
    vec![
        f.nodes as f64 / denom_nodes,
        f.edges as f64 / denom_edges,
        f.depth as f64 / (max_nodes.max(1) as f64),
        f.scc_count as f64 / (max_nodes.max(1) as f64),
        f.failure_rate,
        f.reward_trend,
        f.avg_out_degree / 10.0,
        f.avg_in_degree / 10.0,
        f.branching_factor / 10.0,
        f.leaf_count as f64 / denom_nodes,
        f.root_count as f64 / denom_nodes,
        f.verify_to_mutate_ratio,
        f.observe_to_mutate_ratio,
        f.node_type_entropy,
        f.avg_node_priority / 10.0,
        f.avg_node_budget / 10.0,
        f.blocked_fraction,
        f.ready_fraction,
        f.failed_fraction,
        f.completion_velocity,
        f.retry_rate,
        f.failure_pattern_rate,
        f.cycle_frequency,
        f.deadlock_rate,
    ]
}

pub fn node_utility(graph: &dag::TaskGraph, node_id: &str, iter: u64) -> f64 {
    let node = match graph.nodes.iter().find(|n| n.id == node_id) {
        Some(n) => n,
        None => return 0.0,
    };
    let dependents = graph.nodes.iter().filter(|n| n.deps.iter().any(|d| d == node_id)).count();
    let completion_value = if node.status == dag::Status::Completed && node.error.is_none() { 1.0 } else { 0.0 };
    let age = node.completed_iter.map(|t| iter.saturating_sub(t)).unwrap_or(0) as f64;
    0.6 * dependents as f64 + 0.3 * completion_value - 0.1 * age
}

pub fn edge_count(graph: &dag::TaskGraph) -> usize {
    graph.nodes.iter().map(|n| n.deps.len()).sum()
}

pub fn graph_signature(graph: &dag::TaskGraph) -> String {
    let mut nodes = graph
        .nodes
        .iter()
        .map(|n| {
            let mut caps: Vec<Capability> = n.required_capabilities.clone();
            caps.sort_by_key(|c| format!("{:?}", c));
            (n.id.clone(), format!("{:?}", n.node_type), caps)
        })
        .collect::<Vec<_>>();
    nodes.sort_by(|a, b| a.0.cmp(&b.0));

    let mut edges = Vec::new();
    for n in &graph.nodes {
        for dep in &n.deps {
            edges.push((dep.clone(), n.id.clone()));
        }
    }
    edges.sort();

    let mut hasher = Fnv64::new();
    hasher.write(b"nodes");
    for (id, node_type, caps) in nodes {
        hasher.write(id.as_bytes());
        hasher.write(node_type.as_bytes());
        for cap in caps {
            hasher.write(format!("{:?}", cap).as_bytes());
        }
    }
    hasher.write(b"edges");
    for (from, to) in edges {
        hasher.write(from.as_bytes());
        hasher.write(to.as_bytes());
    }
    format!("{:016x}", hasher.finish())
}

fn compute_max_depth(graph: &dag::TaskGraph) -> usize {
    if graph.nodes.is_empty() {
        return 0;
    }
    let id_to_idx: HashMap<&str, usize> = graph.nodes.iter().enumerate().map(|(i, n)| (n.id.as_str(), i)).collect();
    let mut adj: Vec<Vec<usize>> = vec![Vec::new(); graph.nodes.len()];
    for (idx, node) in graph.nodes.iter().enumerate() {
        for dep in &node.deps {
            if let Some(&j) = id_to_idx.get(dep.as_str()) {
                adj[j].push(idx);
            }
        }
    }
    let depth = gpu_kernels::compute_depth(&adj);
    depth.into_iter().map(|d| d.max(0) as usize).max().unwrap_or(0)
}

struct Fnv64 {
    state: u64,
}

impl Fnv64 {
    fn new() -> Self {
        Self { state: 0xcbf29ce484222325 }
    }

    fn write(&mut self, bytes: &[u8]) {
        for b in bytes {
            self.state ^= *b as u64;
            self.state = self.state.wrapping_mul(0x100000001b3);
        }
    }

    fn finish(&self) -> u64 {
        self.state
    }
}

use std::path::Path;

use anyhow::Result;

use super::dag;
use super::graph_algo::{emit_planned_graph, node_utility, run_graph_algorithms};
use super::graph_runtime::{enforce_semantic_validations, prune_unlinked_nodes};

pub struct MaintenanceCtx<'a> {
    pub graph: &'a mut dag::TaskGraph,
    pub log_dir: &'a Path,
    pub iter: u64,
    pub features_retry_rate: f64,
    pub features_failed_fraction: f64,
    pub features_branching_factor: f64,
    pub prune_unlinked: bool,
    pub auto_prune: bool,
    pub prune_min_age: u64,
    pub prune_threshold: f64,
    pub recovery_retry_rate_threshold: f64,
    pub recovery_failed_fraction_threshold: f64,
}

pub(crate) fn prune_low_value_nodes(graph: &mut dag::TaskGraph, iter: u64, auto_prune: bool, prune_min_age: u64, prune_threshold: f64) {
    if !auto_prune {
        return;
    }
    let mut parents = std::collections::HashSet::new();
    for node in &graph.nodes {
        for dep in &node.deps {
            parents.insert(dep.clone());
        }
    }
    let mut pruned = Vec::new();
    for node in &graph.nodes {
        if node.status != dag::Status::Completed {
            continue;
        }
        if node.deps.is_empty() {
            continue;
        }
        if parents.contains(&node.id) {
            continue;
        }
        let age = node.completed_iter.map(|t| iter.saturating_sub(t)).unwrap_or(0);
        if age < prune_min_age {
            continue;
        }
        let util = node_utility(graph, &node.id, iter);
        if util < prune_threshold {
            pruned.push(node.id.clone());
        }
    }
    if pruned.is_empty() {
        return;
    }
    graph.nodes.retain(|n| !pruned.contains(&n.id));
    for node in &mut graph.nodes {
        node.deps.retain(|d| !pruned.contains(d));
    }
    graph.rebuild_index();
}

pub(crate) fn apply_recovery(graph: &mut dag::TaskGraph) {
    for node in &mut graph.nodes {
        if node.status == dag::Status::Failed {
            node.status = dag::Status::Pending;
            node.readonly_fail_count = 0;
            node.error = None;
            node.result = None;
        }
    }
    graph.rebuild_index();
}

pub fn maintain_graph(ctx: MaintenanceCtx<'_>) -> Result<()> {
    super::ensure_unique_node_ids(&mut ctx.graph.nodes);
    let iter_u32 = u32::try_from(ctx.iter).unwrap_or(u32::MAX);
    emit_planned_graph(ctx.graph, ctx.log_dir, iter_u32);
    run_graph_algorithms(ctx.graph, ctx.log_dir, iter_u32);

    if ctx.prune_unlinked {
        prune_unlinked_nodes(ctx.graph);
    }
    enforce_semantic_validations(ctx.graph)?;
    prune_low_value_nodes(ctx.graph, ctx.iter, ctx.auto_prune, ctx.prune_min_age, ctx.prune_threshold);
    let risk = risk_score(ctx.features_retry_rate, ctx.features_failed_fraction, ctx.features_branching_factor);
    let threshold = (ctx.recovery_retry_rate_threshold + ctx.recovery_failed_fraction_threshold) / 2.0;
    if risk > threshold {
        apply_recovery(ctx.graph);
    }
    Ok(())
}

fn risk_score(retry_rate: f64, failed_fraction: f64, branching_factor: f64) -> f64 {
    let w1 = 0.5;
    let w2 = 0.4;
    let w3 = 0.1;
    let branching_norm = (branching_factor / 4.0).min(1.0);
    (w1 * retry_rate) + (w2 * failed_fraction) + (w3 * branching_norm)
}

use anyhow::Result;
use std::collections::HashMap;
use std::path::Path;

use super::dag;
use super::dag::ContextNode;
use super::decompose;
#[cfg(feature = "cuda")]
use algorithms::graph::model_checking;
use algorithms::graph::{csr::Csr, reachability, scc, topological_sort};

struct GraphKernels {
    adj: Vec<Vec<usize>>,
    csr: Csr,
    topo: Vec<usize>,
    sccs: Vec<Vec<usize>>,
}

fn build_kernels(graph: &dag::TaskGraph) -> GraphKernels {
    let id_to_idx: HashMap<&str, usize> = graph.nodes.iter().enumerate().map(|(i, n)| (n.id.as_str(), i)).collect();
    let mut adj: Vec<Vec<usize>> = vec![Vec::new(); graph.nodes.len()];
    for n in &graph.nodes {
        let to = match id_to_idx.get(n.id.as_str()) {
            Some(v) => *v,
            None => continue,
        };
        for dep in &n.deps {
            if let Some(from) = id_to_idx.get(dep.as_str()) {
                adj[*from].push(to);
            }
        }
    }
    let csr = Csr::from_adj(&adj);
    let topo = topological_sort::topological_sort(&adj);
    let sccs = scc::kosaraju_scc(&adj);
    GraphKernels { adj, csr, topo, sccs }
}

fn prune_roots(kernels: &GraphKernels) -> Vec<usize> {
    let all: std::collections::HashSet<usize> = kernels.topo.iter().chain(kernels.sccs.iter().flatten()).copied().collect();
    all.into_iter().filter(|&i| !kernels.adj[i].is_empty()).collect()
}

pub(crate) fn build_context(graph: &dag::TaskGraph, node_id: &str, radius: usize) -> Vec<ContextNode> {
    if radius == 0 {
        return Vec::new();
    }
    let id_to_idx: HashMap<&str, usize> = graph.nodes.iter().enumerate().map(|(i, n)| (n.id.as_str(), i)).collect();
    let mut rev_adj: Vec<Vec<usize>> = vec![Vec::new(); graph.nodes.len()];
    for (idx, node) in graph.nodes.iter().enumerate() {
        for dep in &node.deps {
            if let Some(dep_idx) = id_to_idx.get(dep.as_str()) {
                rev_adj[idx].push(*dep_idx);
            }
        }
    }
    let csr = Csr::from_adj(&rev_adj);
    let start = graph.nodes.iter().position(|n| n.id == node_id);
    let roots: Vec<usize> = start.into_iter().collect();
    let reach = reachability::reachability_bounded(&csr, &roots, radius);

    let by_id: HashMap<&str, &dag::TaskNode> = graph.nodes.iter().map(|n| (n.id.as_str(), n)).collect();

    let failure_summary = graph
        .nodes
        .iter()
        .enumerate()
        .filter(|(i, n)| reach.get(*i).copied().unwrap_or(false) && n.status == dag::Status::Failed)
        .filter_map(|(_, n)| n.error.as_deref().map(|e| format!("{}: {}", n.id, e)))
        .collect::<Vec<_>>()
        .join("\n");
    let failure_summary = if failure_summary.is_empty() { None } else { Some(failure_summary) };

    graph
        .nodes
        .iter()
        .enumerate()
        .filter(|(i, _)| reach.get(*i).copied().unwrap_or(false))
        .map(|(_, n)| {
            let causal_summary = n
                .deps
                .iter()
                .filter_map(|dep_id| by_id.get(dep_id.as_str()))
                .filter(|dep| dep.status == dag::Status::Completed)
                .filter_map(|dep| dep.result.as_deref())
                .collect::<Vec<_>>()
                .join("\n---\n");
            let causal_summary = if causal_summary.is_empty() { None } else { Some(causal_summary) };
            ContextNode {
                id: n.id.clone(),
                description: n.description.clone(),
                node_type: n.node_type,
                deps: n.deps.clone(),
                required_capabilities: n.required_capabilities.clone(),
                status: n.status,
                result: n.result.clone(),
                error: n.error.clone(),
                causal_summary,
                failure_summary: failure_summary.clone(),
            }
        })
        .collect()
}

pub(crate) fn prune_unlinked_nodes(graph: &mut dag::TaskGraph) {
    if graph.nodes.is_empty() {
        return;
    }
    let kernels = build_kernels(graph);
    let roots = prune_roots(&kernels);
    if roots.is_empty() {
        // Treat isolated nodes as roots to avoid wiping early graphs.
        return;
    }
    let reach = reachability::reachability_gpu(&kernels.csr, &roots);
    let mut next = Vec::with_capacity(graph.nodes.len());
    for (idx, node) in graph.nodes.iter().enumerate() {
        if reach.get(idx).copied().unwrap_or(false) {
            next.push(node.clone());
        }
    }
    graph.nodes = next;
}

pub(crate) fn enforce_semantic_validations(graph: &dag::TaskGraph) -> Result<()> {
    // 0) Assertion checking: invariant must hold for every node (GPU when available).
    assert_invariants_all_states(graph)?;

    // 1) All render nodes must be reachable from at least one analysis node.
    let kernels = build_kernels(graph);
    let analysis_roots: Vec<usize> = graph.nodes.iter().enumerate().filter_map(|(i, n)| (n.node_type == decompose::NodeType::Analysis).then_some(i)).collect();
    let reach = reachability::reachability_gpu(&kernels.csr, &analysis_roots);
    for (idx, n) in graph.nodes.iter().enumerate() {
        if n.node_type == decompose::NodeType::Render && !reach.get(idx).copied().unwrap_or(false) {
            return Err(anyhow::anyhow!("render node {} not reachable from analysis node", n.id));
        }
    }

    // 2) Model-check invariant on reachable nodes (GPU when available).
    let invariant_mask: Vec<u8> = graph
        .nodes
        .iter()
        .map(|n| {
            let ok = !n.description.trim().is_empty() && !n.required_capabilities.is_empty();
            ok as u8
        })
        .collect();
    #[cfg(feature = "cuda")]
    {
        let ok = model_checking::model_check_gpu(&kernels.csr, &analysis_roots, &invariant_mask);
        if !ok {
            return Err(anyhow::anyhow!("model check failed: invariant violation on reachable node"));
        }
    }
    #[cfg(not(feature = "cuda"))]
    {
        for (idx, ok) in invariant_mask.iter().enumerate() {
            if reach.get(idx).copied().unwrap_or(false) && *ok == 0 {
                return Err(anyhow::anyhow!("model check failed: invariant violation on reachable node"));
            }
        }
    }

    // 2) No depth beyond max_depth (approx by DFS).
    // This will be checked elsewhere by limiting expansion; kept as sanity.
    Ok(())
}

fn assert_invariants_all_states(graph: &dag::TaskGraph) -> Result<()> {
    if graph.nodes.is_empty() {
        return Ok(());
    }
    let kernels = build_kernels(graph);
    let invariant_mask: Vec<u8> = graph
        .nodes
        .iter()
        .map(|n| {
            let ok = !n.id.trim().is_empty() && !n.description.trim().is_empty() && !n.required_capabilities.is_empty() && !n.deps.iter().any(|d| d == &n.id);
            ok as u8
        })
        .collect();
    let roots: Vec<usize> = (0..graph.nodes.len()).collect();
    #[cfg(feature = "cuda")]
    {
        let ok = model_checking::model_check_gpu(&kernels.csr, &roots, &invariant_mask);
        if !ok {
            return Err(anyhow::anyhow!("assertion check failed: invariant violated"));
        }
    }
    #[cfg(not(feature = "cuda"))]
    {
        for (idx, ok) in invariant_mask.iter().enumerate() {
            if *ok == 0 {
                return Err(anyhow::anyhow!("assertion check failed: invariant violated at node {}", graph.nodes[idx].id));
            }
        }
    }
    Ok(())
}

