#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct EdgeSpec {
    pub from: String,
    pub to: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RetractSpec {
    pub id: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RewriteSpec {
    pub id: String,
    pub new_description: String,
    pub new_capabilities: Vec<Capability>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PlannerUpdate {
    #[serde(default)]
    pub new_nodes: Vec<TaskSpec>,
    #[serde(default)]
    pub new_edges: Vec<EdgeSpec>,
    #[serde(default)]
    pub retract_nodes: Vec<RetractSpec>,
    #[serde(default)]
    pub rewrite_nodes: Vec<RewriteSpec>,
}

pub fn apply_planner_update(graph: &mut TaskGraph, update: PlannerUpdate) -> Result<()> {
    let retract_ids: HashSet<String> =
        update.retract_nodes.into_iter().filter_map(|spec| graph.nodes.iter().find(|n| n.id == spec.id).filter(|n| matches!(n.status, Status::Pending | Status::Failed)).map(|_| spec.id)).collect();

    if !retract_ids.is_empty() {
        graph.nodes.retain(|n| !retract_ids.contains(&n.id));
        for node in &mut graph.nodes {
            node.deps.retain(|d| !retract_ids.contains(d));
        }
        graph.rebuild_index();
    }

    for spec in update.rewrite_nodes {
        if let Some(node) = graph.get_node_mut(&spec.id) {
            if node.status == Status::Pending {
                let caps: HashSet<_> = spec.new_capabilities.iter().copied().collect();
                assert_class_disjoint(&caps).map_err(|e| anyhow::anyhow!(e))?;
                node.description = spec.new_description;
                node.required_capabilities = spec.new_capabilities;
            }
        }
    }

    let existing: HashSet<String> = graph.nodes.iter().map(|n| n.id.clone()).collect();

    graph.nodes.extend(update.new_nodes.into_iter().filter(|s| !existing.contains(&s.id)).map(|spec| TaskNode {
        id: spec.id,
        description: spec.description,
        status: Status::Pending,
        deps: spec.deps,
        required_capabilities: spec.required_capabilities,
        node_type: spec.node_type,
        priority: spec.priority,
        budget: spec.budget,
        reasoning_trace: spec.reasoning_trace,
        result: None,
        error: None,
        readonly_fail_count: 0,
        repair_attempts: 0,
        completed_iter: None,
    }));

    let id_to_idx: HashMap<String, usize> = graph.nodes.iter().enumerate().map(|(i, n)| (n.id.clone(), i)).collect();

    for edge in update.new_edges {
        if let Some(&to_idx) = id_to_idx.get(&edge.to) {
            let deps = &mut graph.nodes[to_idx].deps;
            if !deps.contains(&edge.from) {
                deps.push(edge.from);
            }
        }
    }
    Ok(())
}

use rand::Rng;
use serde::{Deserialize, Serialize};
use std::path::Path;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PolicyWeights {
    #[serde(default)]
    pub planner_bias: Vec<f64>,
    #[serde(default)]
    pub node_add_bias: Vec<f64>,
    #[serde(default)]
    pub edge_add_bias: Vec<f64>,
    #[serde(default)]
    pub rewrite_bias: Vec<f64>,
    #[serde(default)]
    pub run_planner_head: Vec<f64>,
    #[serde(default)]
    pub expansion_head: Vec<f64>,
    #[serde(default)]
    pub execution_head: Vec<f64>,
    #[serde(default)]
    pub unblock_head: Vec<f64>,
}

#[derive(Debug, Clone)]
pub struct PolicyModel {
    pub(crate) weights: PolicyWeights,
}

#[derive(Debug, Clone)]
pub struct PolicyBias {
    pub planner_bias: f64,
    pub node_add_bias: f64,
    pub edge_add_bias: f64,
    pub rewrite_bias: f64,
}

#[derive(Debug, Clone)]
pub struct PolicyDecision {
    pub run_planner: bool,
    pub expansion_scale: f64,
    pub prioritize_unblock: bool,
    pub execution_preference: f64,
}

impl PolicyModel {
    pub fn load_default() -> Self {
        let path = Path::new("/workspace/ai_sandbox/canon/agent_logs/policy_weights.json");
        Self::load(path)
    }

    pub fn load(path: &Path) -> Self {
        let weights = std::fs::read_to_string(path).ok().and_then(|s| serde_json::from_str::<PolicyWeights>(&s).ok()).unwrap_or_else(default_weights);
        Self { weights }
    }

    pub fn save(&self, path: &Path) -> Result<(), std::io::Error> {
        let json = serde_json::to_string_pretty(&self.weights).unwrap_or_default();
        std::fs::write(path, json)
    }

    pub fn predict(&self, features: &[f64]) -> PolicyBias {
        let fv = features;
        let dot = |w: &Vec<f64>| -> f64 { w.iter().zip(fv.iter()).map(|(a, b)| a * b).sum() };
        PolicyBias {
            planner_bias: dot(&self.weights.planner_bias),
            node_add_bias: dot(&self.weights.node_add_bias),
            edge_add_bias: dot(&self.weights.edge_add_bias),
            rewrite_bias: dot(&self.weights.rewrite_bias),
        }
    }

    pub fn decide(&self, features: &[f64]) -> PolicyDecision {
        let dot = |w: &Vec<f64>| -> f64 { w.iter().zip(features.iter()).map(|(a, b)| a * b).sum() };
        let raw_run = dot(&self.weights.run_planner_head);
        let raw_expand = dot(&self.weights.expansion_head);
        let raw_exec = dot(&self.weights.execution_head);
        let raw_unblock = dot(&self.weights.unblock_head);
        let run_planner = raw_run >= 0.0;
        let expansion_scale = (1.0 + raw_expand).clamp(0.5, 2.0);
        let execution_preference = raw_exec.clamp(-1.0, 1.0);
        let prioritize_unblock = raw_unblock > 0.0;
        PolicyDecision { run_planner, expansion_scale, prioritize_unblock, execution_preference }
    }

    pub fn weight_norm(&self) -> f64 {
        let all = self
            .weights
            .planner_bias
            .iter()
            .chain(self.weights.node_add_bias.iter())
            .chain(self.weights.edge_add_bias.iter())
            .chain(self.weights.rewrite_bias.iter())
            .chain(self.weights.run_planner_head.iter())
            .chain(self.weights.expansion_head.iter())
            .chain(self.weights.execution_head.iter())
            .chain(self.weights.unblock_head.iter());
        all.map(|v| v * v).sum::<f64>().sqrt()
    }
}

fn default_weights() -> PolicyWeights {
    PolicyWeights {
        planner_bias: vec![0.2, 0.0, 0.0, 0.0],
        node_add_bias: vec![0.2, 0.0, 0.0, 0.0],
        edge_add_bias: vec![0.1, 0.0, 0.0, 0.0],
        rewrite_bias: vec![0.1, 0.0, 0.0, 0.0],
        run_planner_head: vec![0.3, 0.0, 0.0, 0.0],
        expansion_head: vec![0.2, 0.0, 0.0, 0.0],
        // Bias toward execution by default when no weights are present.
        execution_head: vec![0.8, 0.0, 0.0, 0.0],
        unblock_head: vec![0.2, 0.0, 0.0, 0.0],
    }
}

pub fn format_bias(bias: &PolicyBias) -> String {
    if bias.planner_bias == 0.0 && bias.node_add_bias == 0.0 && bias.edge_add_bias == 0.0 && bias.rewrite_bias == 0.0 {
        return String::new();
    }
    format!(
        "Policy bias:\nplanner_bias={:.3}\nnode_add_bias={:.3}\nedge_add_bias={:.3}\nrewrite_bias={:.3}\n\
Prefer actions with positive bias and avoid strongly negative bias.\n",
        bias.planner_bias, bias.node_add_bias, bias.edge_add_bias, bias.rewrite_bias
    )
}

pub fn smooth_bias(prev: Option<&PolicyBias>, next: PolicyBias) -> PolicyBias {
    if let Some(p) = prev {
        PolicyBias {
            planner_bias: 0.8 * p.planner_bias + 0.2 * next.planner_bias,
            node_add_bias: 0.8 * p.node_add_bias + 0.2 * next.node_add_bias,
            edge_add_bias: 0.8 * p.edge_add_bias + 0.2 * next.edge_add_bias,
            rewrite_bias: 0.8 * p.rewrite_bias + 0.2 * next.rewrite_bias,
        }
    } else {
        next
    }
}

pub fn maybe_explore(mut bias: PolicyBias, epsilon: f64) -> PolicyBias {
    let mut rng = rand::thread_rng();
    if rng.r#gen::<f64>() < epsilon {
        bias.planner_bias = 0.0;
        bias.node_add_bias = 0.0;
        bias.edge_add_bias = 0.0;
        bias.rewrite_bias = 0.0;
    }
    bias
}

use super::graph_algo::normalize_features;
use super::policy::{PolicyBias, PolicyDecision, PolicyModel};

pub struct PolicyOutcome {
    pub normalized: Vec<f64>,
    pub bias: PolicyBias,
    pub decision: PolicyDecision,
    pub weight_norm: f64,
}

pub fn evaluate(features: &super::graph_algo::FeatureVector, max_nodes: usize, max_edges: usize) -> PolicyOutcome {
    let normalized = normalize_features(features, max_nodes, max_edges);
    let model = PolicyModel::load_default();
    let bias = model.predict(&normalized);
